OBSERVATION = {'data': [[None, None, None, None, None, None], ['B', None, None, 'W', None, 'B'], [None, None, None, None, None, None], [None, None, None, None, 'W', None], [None, 'W', 'W', None, None, 'B'], [None, 'W', None, 'B', None, None]]}

def solve(observation):
    grid = [row[:] for row in observation['data']]
    N = len(grid)

    def is_consistent(g):
        # Check rows and columns for counts and consecutive cells
        for i in range(N):
            row = g[i]
            col = [g[r][i] for r in range(N)]
            if not check_line(row) or not check_line(col):
                return False

        # Check uniqueness of full rows and columns
        rows = [tuple(r) for r in g if None not in r]
        if len(rows) != len(set(rows)): return False
        cols = []
        for c in range(N):
            col = [g[r][c] for r in range(N)]
            if None not in col:
                cols.append(tuple(col))
        if len(cols) != len(set(cols)): return False

        return True

    def check_line(line):
        bc = line.count('B')
        wc = line.count('W')
        if bc > N // 2 or wc > N // 2:
            return False
        for i in range(N - 2):
            if line[i] is not None and line[i] == line[i+1] == line[i+2]:
                return False
        return True

    def propagate(g):
        changed = True
        while changed:
            changed = False
            # Rule 1: No three consecutive
            for r in range(N):
                for c in range(N):
                    if g[r][c] is None:
                        for color in ['B', 'W']:
                            other = 'W' if color == 'B' else 'B'
                            # Check horizontal
                            if (c >= 2 and g[r][c-1] == color and g[r][c-2] == color) or \
                               (c <= N-3 and g[r][c+1] == color and g[r][c+2] == color) or \
                               (c >= 1 and c <= N-2 and g[r][c-1] == color and g[r][c+1] == color):
                                g[r][c] = other
                                changed = True
                                break
                            # Check vertical
                            if (r >= 2 and g[r-1][c] == color and g[r-2][c] == color) or \
                               (r <= N-3 and g[r+1][c] == color and g[r+2][c] == color) or \
                               (r >= 1 and r <= N-2 and g[r-1][c] == color and g[r+1][c] == color):
                                g[r][c] = other
                                changed = True
                                break

            # Rule 2: Equal counts
            for i in range(N):
                # Rows
                row = g[i]
                bc, wc = row.count('B'), row.count('W')
                if bc == N // 2 and wc < N // 2:
                    for c in range(N):
                        if g[i][c] is None: g[i][c] = 'W'; changed = True
                elif wc == N // 2 and bc < N // 2:
                    for c in range(N):
                        if g[i][c] is None: g[i][c] = 'B'; changed = True
                # Cols
                col = [g[r][i] for r in range(N)]
                bc, wc = col.count('B'), col.count('W')
                if bc == N // 2 and wc < N // 2:
                    for r in range(N):
                        if g[r][i] is None: g[r][i] = 'W'; changed = True
                elif wc == N // 2 and bc < N // 2:
                    for r in range(N):
                        if g[r][i] is None: g[r][i] = 'B'; changed = True

            if not is_consistent(g):
                return None
        return g

    def backtrack(g):
        g = propagate([row[:] for row in g])
        if g is None: return None

        # Find first empty cell
        empty_cell = None
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    empty_cell = (r, c)
                    break
            if empty_cell: break

        if not empty_cell:
            return g if is_consistent(g) else None

        r, c = empty_cell
        for color in ['B', 'W']:
            g[r][c] = color
            res = backtrack(g)
            if res: return res
            g[r][c] = None
        return None

    result = backtrack(grid)
    return result if result else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

