                bc, wc = col.count('B'), col.count('W')
                if bc == target or wc == target:
                    fill = 'W' if bc == target else 'B'
                    for r in range(N):
                        if g[r][c] is None:
                            g[r][c] = fill
                            changed = True

            # Validate state after deductions
            if not is_consistent(g):
                return False
            if not changed:
                break
        return True

    def backtrack(g):
        # Apply logical deductions first to prune search space
        if not apply_deductions(g):
            return None

        # Check if grid is complete
        if all(None not in row for row in g):
            return g

        # Find the first empty cell to branch on
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    # Try both possibilities
                    for val in ['B', 'W']:
                        new_g = [row[:] for row in g]
                        new_g[r][c] = val
                        res = backtrack(new_g)
                        if res:
                            return res
                    return None
        return None

    # Start solving from the initial state
    result = backtrack([row[:] for row in initial_grid])
    return result if result else "No Solution"

