def solve(observation):
    grid_data = observation['data']
    n = len(grid_data)

    def is_valid(grid):
        # Check rows and columns for 3 consecutive same colors
        for i in range(n):
            for j in range(n - 2):
                if grid[i][j] and grid[i][j] == grid[i][j+1] == grid[i][j+2]:
                    return False
                if grid[j][i] and grid[j][i] == grid[j+1][i] == grid[j+2][i]:
                    return False

        # Check counts of B and W in rows and columns
        for i in range(n):
            row = grid[i]
            col = [grid[r][i] for r in range(n)]
            if row.count('B') > n // 2 or row.count('W') > n // 2:
                return False
            if col.count('B') > n // 2 or col.count('W') > n // 2:
                return False

        # Check for duplicate full rows and columns
        rows = [tuple(r) for r in grid if None not in r]
        if len(rows) != len(set(rows)):
            return False
        cols = [tuple(grid[r][c] for r in range(n)) for c in range(n) if all(grid[r][c] is not None for r in range(n))]
        if len(cols) != len(set(cols)):
            return False

        return True

    def apply_rules(grid):
        changed = True
        while changed:
            changed = False
            # Rule 1: Two adjacent same colors -> neighbors must be opposite
            for i in range(n):
                for j in range(n):
                    if grid[i][j] is None:
                        # Horizontal
                        if j > 1 and grid[i][j-1] == grid[i][j-2] and grid[i][j-1] is not None:
                            grid[i][j] = 'B' if grid[i][j-1] == 'W' else 'W'
                            changed = True
                        elif j < n - 2 and grid[i][j+1] == grid[i][j+2] and grid[i][j+1] is not None:
                            grid[i][j] = 'B' if grid[i][j+1] == 'W' else 'W'
                            changed = True
                        # Vertical
                        if i > 1 and grid[i-1][j] == grid[i-2][j] and grid[i-1][j] is not None:
                            grid[i][j] = 'B' if grid[i-1][j] == 'W' else 'W'
                            changed = True
                        elif i < n - 2 and grid[i+1][j] == grid[i+2][j] and grid[i+1][j] is not None:
                            grid[i][j] = 'B' if grid[i+1][j] == 'W' else 'W'
                            changed = True
                        # Rule 2: Gap between two same colors -> gap must be opposite
                        if 0 < j < n - 1 and grid[i][j-1] == grid[i][j+1] and grid[i][j-1] is not None:
                            grid[i][j] = 'B' if grid[i][j-1] == 'W' else 'W'
                            changed = True
