            for i in range(n):
                row = grid[i]
                if row.count('B') == n // 2 and row.count(None) > 0:
                    grid[i] = ['W' if x is None else x for x in row]
                    changed = True
                elif row.count('W') == n // 2 and row.count(None) > 0:
                    grid[i] = ['B' if x is None else x for x in row]
                    changed = True

                col = [grid[r][i] for r in range(n)]
