def is_legal(grid, r, c, val, N):
    # Check row consecutive
    if c >= 2 and grid[r][c-1] == val and grid[r][c-2] == val: return False
    if 1 <= c < N-1 and grid[r][c-1] == val and grid[r][c+1] == val: return False
    if c < N-2 and grid[r][c+1] == val and grid[r][c+2] == val: return False

    # Check col consecutive
    if r >= 2 and grid[r-1][c] == val and grid[r-2][c] == val: return False
    if 1 <= r < N-1 and grid[r-1][c] == val and grid[r+1][c] == val: return False
    if r < N-2 and grid[r+1][c] == val and grid[r+2][c] == val: return False

    # Check row count
    row_count = 0
    for i in range(N):
        if grid[r][i] == val:
            row_count += 1
    if row_count >= N // 2: return False

    # Check col count
    col_count = 0
    for i in range(N):
        if grid[i][c] == val:
            col_count += 1
    if col_count >= N // 2: return False

    return True

def check_uniqueness(grid, N):
    # Check full rows uniqueness
    rows = [tuple(r) for r in grid if None not in r]
    if len(rows) != len(set(rows)): return False

    # Check full columns uniqueness
    cols = []
    for c in range(N):
        col = tuple(grid[r][c] for r in range(N))
        if None not in col:
            cols.append(col)
    if len(cols) != len(set(cols)): return False

    return True

def apply_deductions(grid, N):
    while True:
        changed = False
        for r in range(N):
            row = grid[r]
            b_count = row.count('B')
            w_count = row.count('W')
            n_count = row.count(None)
            if n_count > 0:
                if b_count == N // 2:
                    for c in range(N):
                        if grid[r][c] is None:
                            grid[r][c] = 'W'
                            changed = True
                elif w_count == N // 2:
                    for c in range(N):
                        if grid[r][c] is None:
                            grid[r][c] = 'B'
                            changed = True
                elif b_count + n_count < N // 2 or w_count + n_count < N // 2:
                    return False

        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            b_count = col.count('B')
            w_count = col.count('W')
            n_count = col.count(None)
            if n_count > 0:
                if b_count == N // 2:
                    for r in range(N):
