            for c in range(N):
                if grid[r][c] is None:
                    can_B = is_legal(grid, r, c, 'B', N)
                    can_W = is_legal(grid, r, c, 'W', N)
                    if not can_B and not can_W: return False
                    if not can_B:
                        grid[r][c] = 'W'
                        changed = True
                    elif not can_W:
                        grid[r][c] = 'B'
                        changed = True

        if not check_uniqueness(grid, N): return False
        if not changed: break
    return True

def backtrack(grid, N):
    if not apply_deductions(grid, N):
        return None

    empty_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                empty_cell = (r, c)
                break
        if empty_cell: break

    if not empty_cell:
        return grid

    r, c = empty_cell
    for val in ['B', 'W']:
        if is_legal(grid, r, c, val, N):
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val
            res = backtrack(new_grid, N)
            if res: return res
    return None

