        return None

    empty_cell = None
    for r in range(N):
        for c in range(N):
            if grid[r][c] is None:
                empty_cell = (r, c)
                break
        if empty_cell: break

    if not empty_cell:
        return grid

    r, c = empty_cell
    for val in ['B', 'W']:
        if is_legal(grid, r, c, val, N):
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val
            res = backtrack(new_grid, N)
            if res: return res
    return None

def solve(observation):
    grid = [row[:] for row in observation['data']]
    N = len(grid)
    solution = backtrack(grid, N)
    return solution if solution else "No Solution"

