def solve(observation):
    grid_data = observation['data']
    rows = len(grid_data)
    cols = len(grid_data[0])

    # Parse constraints
    h_constraints = {}
    for k, v in observation.get('horizontal', {}).items():
        r, c_mid = ast.literal_eval(k)
        h_constraints[(int(r), int(c_mid - 0.5))] = v

    v_constraints = {}
    for k, v in observation.get('vertical', {}).items():
