        row_vals = [grid[r][j] for j in range(cols) if grid[r][j] is not None]
        col_vals = [grid[i][c] for i in range(rows) if grid[i][c] is not None]
        if row_vals.count(val) > cols // 2: return False
        if col_vals.count(val) > rows // 2: return False

        # Rule 2: No three consecutive same colors
        # Horizontal
        for j in range(max(0, c-2), min(cols-2, c+1)):
            if grid[r][j] == grid[r][j+1] == grid[r][j+2] == val: return False
        # Vertical
        for i in range(max(0, r-2), min(rows-2, r+1)):
            if grid[i][c] == grid[i+1][c] == grid[i+2][c] == val: return False

        # Rule 3 & 4: Constraints
        # Horizontal constraints
        if (r, c) in h_constraints:
            other = grid[r][c+1]
            if other is not None:
                if h_constraints[(r, c)] == '=' and val != other: return False
                if h_constraints[(r, c)] == 'x' and val == other: return False
        if (r, c-1) in h_constraints:
            other = grid[r][c-1]
            if other is not None:
