    }
}

def solve(observation):
    data = observation['data']
    N = len(data)

    # Parse constraints into a more usable format
    horiz = {}
    for k, v in observation['horizontal'].items():
        r, c_mid = ast.literal_eval(k)
        c1, c2 = int(c_mid - 0.5), int(c_mid + 0.5)
        horiz[(r, c1, r, c2)] = v

    vert = {}
    for k, v in observation['vertical'].items():
        r_mid, c = ast.literal_eval(k)
        r1, r2 = int(r_mid - 0.5), int(r_mid + 0.5)
        vert[(r1, c, r2, c)] = v

    def is_valid(grid, r, c, val):
        # Row and column check
        for i in range(N):
            if grid[r][i] == val or grid[i][c] == val:
                return False

        # Horizontal constraints
        # Check left neighbor
        if c > 0:
            left_val = grid[r][c-1]
            if left_val is not None:
                if (r, c-1, r, c) in horiz:
                    op = horiz[(r, c-1, r, c)]
                    if op == '>' and not (left_val > val): return False
                    if op == '<' and not (left_val < val): return False
        # Check right neighbor
        if c < N - 1:
            right_val = grid[r][c+1]
            if right_val is not None:
                if (r, c, r, c+1) in horiz:
                    op = horiz[(r, c, r, c+1)]
                    if op == '>' and not (val > right_val): return False
                    if op == '<' and not (val < right_val): return False

        # Vertical constraints
        # Check top neighbor
        if r > 0:
            top_val = grid[r-1][c]
            if top_val is not None:
                if (r-1, c, r, c) in vert:
                    op = vert[(r-1, c, r, c)]
                    if op == 'v' and not (top_val > val): return False
                    if op == '^' and not (top_val < val): return False
        # Check bottom neighbor
        if r < N - 1:
            bot_val = grid[r+1][c]
            if bot_val is not None:
                if (r, c, r+1, c) in vert:
                    op = vert[(r, c, r+1, c)]
                    if op == 'v' and not (val > bot_val): return False
                    if op == '^' and not (val < bot_val): return False

        return True

    def get_possibilities(grid, r, c):
        if grid[r][c] is not None:
            return [grid[r][c]]

        possible = set(range(1, N + 1))
        # Row/Col constraints
        for i in range(N):
            if grid[r][i] in possible: possible.remove(grid[r][i])
            if grid[i][c] in possible: possible.remove(grid[i][c])

        # Inequality pruning
        valid_p = []
        for p in possible:
            if is_valid(grid, r, c, p):
                valid_p.append(p)
        return valid_p

    def backtrack(grid):
        # Find cell with minimum remaining values (MRV heuristic)
        min_p = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    p = get_possibilities(grid, r, c)
                    if not p: return None # Dead end
                    if len(p) < min_p:
                        min_p = len(p)
                        best_cell = (r, c, p)
                        if min_p == 1: break
            if min_p == 1: break

        if best_cell is None:
            return grid # Solved

        r, c, p_list = best_cell
        for val in p_list:
            grid[r][c] = val
            res = backtrack(grid)
            if res: return res
            grid[r][c] = None

        return None

    # Initial grid copy
    grid = [row[:] for row in data]
    solution = backtrack(grid)
    return solution if solution else "No Solution"

