        return True

    def get_possibilities(grid, r, c):
        if grid[r][c] is not None:
            return [grid[r][c]]

        possible = set(range(1, N + 1))
        # Row/Col constraints
        for i in range(N):
            if grid[r][i] in possible: possible.remove(grid[r][i])
            if grid[i][c] in possible: possible.remove(grid[i][c])

        # Inequality pruning
        valid_p = []
        for p in possible:
            if is_valid(grid, r, c, p):
                valid_p.append(p)
        return valid_p

    def backtrack(grid):
        # Find cell with minimum remaining values (MRV heuristic)
        min_p = N + 1
        best_cell = None

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    p = get_possibilities(grid, r, c)
                    if not p: return None # Dead end
                    if len(p) < min_p:
                        min_p = len(p)
                        best_cell = (r, c, p)
                        if min_p == 1: break
            if min_p == 1: break

        if best_cell is None:
            return grid # Solved

        r, c, p_list = best_cell
        for val in p_list:
            grid[r][c] = val
            res = backtrack(grid)
            if res: return res
            grid[r][c] = None

        return None

    # Initial grid copy
    grid = [row[:] for row in data]
    solution = backtrack(grid)
    return solution if solution else "No Solution"

