                new_a = {x for x in domains[r1][c1] if x < max_b}
                if not new_a: return None
                if new_a != domains[r1][c1]:
                    domains[r1][c1] = new_a
                    changed = True
                # Update B based on A: B > min(A)
                min_a = min(domains[r1][c1])
                new_b = {x for x in domains[r2][c2] if x > min_a}
                if not new_b: return None
                if new_b != domains[r2][c2]:
                    domains[r2][c2] = new_b
                    changed = True
        return domains

    def backtrack(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        # Check if solved
        if all(len(domains[r][c]) == 1 for r in range(N) for c in range(N)):
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        # MRV heuristic
        min_options = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_options:
                        min_options = len(domains[r][c])
                        best_cell = (r, c)

