        for val in sorted(list(domains[r][c])):
            new_domains = copy.deepcopy(domains)
            new_domains[r][c] = {val}
            res = backtrack(new_domains)
            if res:
                return res
        return None

    result = backtrack(domains)
    return result if result else "No Solution"

