import collections

# OBSERVATION represents the island layout as an N x N 2D list.
# Coordinates (row, col) with top-left as (0, 0).
OBSERVATION = {
    'data': [
        [None, 2, None, 3, None, 1, None],
        [2, None, None, None, None, None, None],
        [None, None, None, None, 4, None, 4],
        [None, None, None, None, None, None, None],
        [None, 1, None, None, None, None, None],
        [None, None, None, None, 2, None, None],
        [3, None, None, 3, None, None, 3]
    ]
}

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    # Extract island positions and values
    islands = []
    island_map = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is not None:
                island_map[(r, c)] = len(islands)
                islands.append({'pos': (r, c), 'val': grid[r][c]})

    num_islands = len(islands)
    if num_islands == 0:
        return {}

    # Identify potential bridges (straight lines, no islands in between)
    potential_edges = []
    for i in range(num_islands):
        r, c = islands[i]['pos']
        # Look right
        for nc in range(c + 1, cols):
            if grid[r][nc] is not None:
                potential_edges.append((i, island_map[(r, nc)]))
                break
        # Look down
        for nr in range(r + 1, rows):
            if grid[nr][c] is not None:
                potential_edges.append((i, island_map[(nr, c)]))
                break

    num_edges = len(potential_edges)

    # Precompute which potential bridges cross each other
    def get_crossing(e1_idx, e2_idx):
        u1, v1 = potential_edges[e1_idx]
        u2, v2 = potential_edges[e2_idx]
        p1, p2 = islands[u1]['pos'], islands[v1]['pos']
        p3, p4 = islands[u2]['pos'], islands[v2]['pos']

        # e1 is horizontal, e2 is vertical
        if p1[0] == p2[0] and p3[1] == p4[1]:
            r, c = p1[0], p3[1]
            c_min, c_max = min(p1[1], p2[1]), max(p1[1], p2[1])
            r_min, r_max = min(p3[0], p4[0]), max(p3[0], p4[0])
            return r_min < r < r_max and c_min < c < c_max
        # e1 is vertical, e2 is horizontal
        if p1[1] == p2[1] and p3[0] == p4[0]:
            c, r = p1[1], p3[0]
            r_min, r_max = min(p1[0], p2[0]), max(p1[0], p2[0])
            c_min, c_max = min(p3[1], p4[1]), max(p3[1], p4[1])
            return c_min < c < c_max and r_min < r < r_max
        return False

    adj_cross = [[] for _ in range(num_edges)]
    for i in range(num_edges):
        for j in range(i + 1, num_edges):
            if get_crossing(i, j):
                adj_cross[i].append(j)
                adj_cross[j].append(i)

    # State variables for backtracking
    remaining_vals = [islands[i]['val'] for i in range(num_islands)]
    edge_counts = [0] * num_edges
    active_crossings = [0] * num_edges

    # Precompute edges connected to each island for pruning
    island_potential_edges = [[] for _ in range(num_islands)]
    for e_idx, (u, v) in enumerate(potential_edges):
        island_potential_edges[u].append(e_idx)
        island_potential_edges[v].append(e_idx)

    def is_connected():
        # Check if all islands are reachable from the first island
        adj = collections.defaultdict(list)
        for e_idx, count in enumerate(edge_counts):
            if count > 0:
                u, v = potential_edges[e_idx]
                adj[u].append(v)
                adj[v].append(u)

        visited = {0}
        queue = collections.deque([0])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        return len(visited) == num_islands

    def backtrack(e_idx):
        # Base case: all potential bridges decided
        if e_idx == num_edges:
            if any(remaining_vals): return None
            return is_connected()

        u, v = potential_edges[e_idx]

        # Try placing 0, 1, or 2 bridges
        for count in [0, 1, 2]:
            # Check if this count is valid (island capacity and no crossings)
            if count > 0:
                if active_crossings[e_idx] > 0: continue
                if remaining_vals[u] < count or remaining_vals[v] < count: continue

            # Apply choice
            edge_counts[e_idx] = count
            remaining_vals[u] -= count
            remaining_vals[v] -= count
            if count > 0:
                for other in adj_cross[e_idx]:
                    active_crossings[other] += 1

            # Human-like pruning: check if remaining requirements can still be met
            possible = True
            for i in range(num_islands):
                rem = remaining_vals[i]
                if rem < 0:
                    possible = False
                    break
                max_future = 0
                for o_e_idx in island_potential_edges[i]:
                    if o_e_idx > e_idx and active_crossings[o_e_idx] == 0:
                        max_future += 2
                if rem > max_future:
                    possible = False
                    break

            if possible:
                if backtrack(e_idx + 1):
                    return True

            # Backtrack choice
            if count > 0:
                for other in adj_cross[e_idx]:
                    active_crossings[other] -= 1
            remaining_vals[u] += count
            remaining_vals[v] += count
            edge_counts[e_idx] = 0

        return False

    # Run solver and format output
    if backtrack(0):
        res = {}
        for i, count in enumerate(edge_counts):
            if count > 0:
                u, v = potential_edges[i]
                p1, p2 = islands[u]['pos'], islands[v]['pos']
                res[tuple(sorted((p1, p2)))] = count
        return res
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

