import sys

# Increase recursion depth for deep puzzles
sys.setrecursionlimit(2000)

OBSERVATION = {
    'data': [
        [2, None, None, None, None, None, 2],
        [None, None, None, None, None, None, None],
        [None, 1, None, None, None, None, 2],
        [None, None, None, None, None, None, None],
        [5, None, None, None, None, None, 3],
        [None, None, None, None, None, None, None],
        [4, None, None, None, 3, None, 2]
    ]
}

def solve(observation):
    data = observation['data']
    if not data:
        return "No Solution"
    rows = len(data)
    cols = len(data[0])

    # Extract islands and their targets
    islands = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                islands.append((r, c, data[r][c]))

    if not islands:
        return {}

    num_islands = len(islands)
    island_coords = {(r, c): i for i, (r, c, v) in enumerate(islands)}
    island_targets = [v for r, c, v in islands]

    # Identify potential edges (orthogonal, no islands in between)
    edges = []
    for i in range(num_islands):
        r1, c1, v1 = islands[i]
        # Look right
        for c2 in range(c1 + 1, cols):
            if (r1, c2) in island_coords:
                edges.append((i, island_coords[(r1, c2)]))
                break
        # Look down
        for r2 in range(r1 + 1, rows):
            if (r2, c1) in island_coords:
                edges.append((i, island_coords[(r2, c1)]))
                break

    num_edges = len(edges)
    island_to_edges = [[] for _ in range(num_islands)]
    for ei, (i1, i2) in enumerate(edges):
        island_to_edges[i1].append(ei)
        island_to_edges[i2].append(ei)

    def get_coords(ei):
        i1, i2 = edges[ei]
        return islands[i1][0], islands[i1][1], islands[i2][0], islands[i2][1]

    # Precompute crossing edges
    crossings = [[] for _ in range(num_edges)]
    for e1 in range(num_edges):
        r1a, c1a, r1b, c1b = get_coords(e1)
        is_h1 = (r1a == r1b)
        for e2 in range(e1 + 1, num_edges):
            r2a, c2a, r2b, c2b = get_coords(e2)
            is_h2 = (r2a == r2b)
            if is_h1 != is_h2:
                if is_h1:
                    h_r, h_c_min, h_c_max = r1a, min(c1a, c1b), max(c1a, c1b)
                    v_c, v_r_min, v_r_max = c2a, min(r2a, r2b), max(r2a, r2b)
                else:
                    h_r, h_c_min, h_c_max = r2a, min(c2a, c2b), max(c2a, c2b)
                    v_c, v_r_min, v_r_max = c1a, min(r1a, r1b), max(r1a, r1b)

                if v_r_min < h_r < v_r_max and h_c_min < v_c < h_c_max:
                    crossings[e1].append(e2)
                    crossings[e2].append(e1)

    def propagate(mins, maxs):
        mins, maxs = list(mins), list(maxs)
        changed = True
        while changed:
            changed = False
            for i in range(num_islands):
                target = island_targets[i]
                e_indices = island_to_edges[i]

                total_mins = sum(mins[ej] for ej in e_indices)
                total_maxs = sum(maxs[ej] for ej in e_indices)

                if total_mins > target or total_maxs < target:
                    return None, None

                for ei in e_indices:
                    # Max constraint: an edge cannot exceed target minus mins of other edges
                    new_max = min(maxs[ei], target - (total_mins - mins[ei]))
                    if new_max < maxs[ei]:
                        maxs[ei] = new_max
                        changed = True
                        if maxs[ei] < mins[ei]: return None, None

                    # Min constraint: an edge must be at least target minus maxs of other edges
                    new_min = max(mins[ei], target - (total_maxs - maxs[ei]))
                    if new_min > mins[ei]:
                        mins[ei] = new_min
                        changed = True
                        if mins[ei] > maxs[ei]: return None, None

            # Crossing constraints: if an edge must exist, its crossings cannot
            for ei in range(num_edges):
                if mins[ei] > 0:
                    for ej in crossings[ei]:
                        if maxs[ej] > 0:
                            maxs[ej] = 0
                            changed = True
                            if maxs[ej] < mins[ej]: return None, None
        return mins, maxs

    def is_connected(mins):
        adj = [[] for _ in range(num_islands)]
        for ei, count in enumerate(mins):
            if count > 0:
                u, v = edges[ei]
                adj[u].append(v)
                adj[v].append(u)

        start_node = -1
        for i in range(num_islands):
            if island_targets[i] > 0:
                start_node = i
                break
        if start_node == -1: return True

        visited = [False] * num_islands
        stack = [start_node]
        visited[start_node] = True
        count = 1
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    count += 1
                    stack.append(v)

        needed_count = sum(1 for t in island_targets if t > 0)
        return count == needed_count

    def backtrack(mins, maxs):
        mins, maxs = propagate(mins, maxs)
        if mins is None: return None

        if all(mins[i] == maxs[i] for i in range(num_edges)):
            # Final check for island targets and connectivity
            for i in range(num_islands):
                if sum(mins[ej] for ej in island_to_edges[i]) != island_targets[i]:
                    return None
            if is_connected(mins):
                return mins
            return None

        # Heuristic: pick edge with smallest range > 0
        best_ei = -1
        min_range = 4
        for ei in range(num_edges):
            if mins[ei] < maxs[ei]:
                r = maxs[ei] - mins[ei]
                if r < min_range:
                    min_range = r
                    best_ei = ei

        # Try values from max to min
        for val in range(maxs[best_ei], mins[best_ei] - 1, -1):
            new_mins, new_maxs = list(mins), list(maxs)
            new_mins[best_ei] = new_maxs[best_ei] = val
            res = backtrack(new_mins, new_maxs)
            if res: return res

        return None

    solution_counts = backtrack([0] * num_edges, [2] * num_edges)

    if solution_counts:
        result = {}
        for ei, count in enumerate(solution_counts):
            if count > 0:
                i1, i2 = edges[ei]
                p1 = (islands[i1][0], islands[i1][1])
                p2 = (islands[i2][0], islands[i2][1])
                key = tuple(sorted((p1, p2)))
                result[key] = count
        return result
