                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == 'W':
                        visited.add((nr, nc))
                        stack.append((nr, nc))
            return len(visited) == len(whites)

        r, c = divmod(idx, cols)

