            if backtrack(idx + 1): return True
            grid[r][c] = '.'

        # Try 'W'
        if is_valid(r, c, 'W'):
            grid[r][c] = 'W'
            if backtrack(idx + 1): return True
            grid[r][c] = '.'

        return False

    if backtrack(0):
        return [[('B' if grid[r][c] == 'B' else None) for c in range(cols)] for r in range(rows)]
    return "No Solution"

