                if len(seen_regions) > 2: return False
        return True

    def check_connectivity(grid):
        white_cells = [(r, c) for r in range(grid_size) for c in range(grid_size) if grid[r][c] != 'B']
        if not white_cells: return True

        start = white_cells[0]
        visited = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < grid_size and 0 <= nc < grid_size and (nr, nc) not in visited and grid[nr][nc] != 'B':
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return len(visited) == len(white_cells)

    def backtrack(rid_idx, current_grid):
        if rid_idx == len(region_cells):
            if check_white_segments(current_grid) and check_connectivity(current_grid):
                return current_grid
            return None

        rid = list(region_cells.keys())[rid_idx]
        cells = region_cells[rid]
        target_black = region_clues.get(rid, None)

        # Generate possible black cell combinations for this region
        import itertools
        possible_counts = [target_black] if target_black is not None else range(len(cells) + 1)

        for count in possible_counts:
            for combo in itertools.combinations(cells, count):
                # Try this combination
                new_grid = [row[:] for row in current_grid]
                valid_combo = True
                for r, c in cells:
                    color = 'B' if (r, c) in combo else 'W'
                    if not is_valid(r, c, color, new_grid):
