    initial_grid = [[None for _ in range(grid_size)] for _ in range(grid_size)]
    solution = backtrack(0, initial_grid)

    if solution:
        return [[('B' if solution[r][c] == 'B' else None) for c in range(grid_size)] for r in range(grid_size)]
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
