        [None, None, None, 1, None, None, None, 0, None, None],
        [None, None, None, None, None, None, None, 1, None, None]
    ]
}

def solve(observation):
    region_grid = observation['region']
    clue_grid = observation['data']
    N = len(region_grid)

    # Constants for cell states
    WHITE, BLACK, UNKNOWN = 0, 1, 2

    # Precompute region information
    region_cells = {}
    clues = {}
    cell_to_region = {}
    for r in range(N):
        for c in range(N):
            rid = region_grid[r][c]
            idx = r * N + c
            cell_to_region[idx] = rid
            if rid not in region_cells:
                region_cells[rid] = []
            region_cells[rid].append(idx)
            if clue_grid[r][c] is not None:
                clues[rid] = clue_grid[r][c]

    # Precompute neighbors
    neighbors = [[] for _ in range(N * N)]
    for r in range(N):
        for c in range(N):
            idx = r * N + c
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N:
                    neighbors[idx].append(nr * N + nc)

    # Precompute minimal-3-region segments for Heyawake rule
    minimal_3_region_segments = []
    # Rows
    for r in range(N):
        for i in range(N):
            for j in range(i + 1, N):
                regs = [region_grid[r][k] for k in range(i, j + 1)]
                seq = [regs[0]]
                for k in range(1, len(regs)):
                    if regs[k] != regs[k-1]: seq.append(regs[k])
                if len(seq) >= 3:
                    # Check if minimal
                    is_minimal = True
                    for start, end in [(i+1, j), (i, j-1)]:
                        sub_regs = [region_grid[r][k] for k in range(start, end + 1)]
                        sub_seq = [sub_regs[0]]
                        for k in range(1, len(sub_regs)):
                            if sub_regs[k] != sub_seq[-1]: sub_seq.append(sub_regs[k])
                        if len(sub_seq) >= 3: is_minimal = False; break
                    if is_minimal:
                        minimal_3_region_segments.append([r * N + k for k in range(i, j + 1)])
    # Columns
    for c in range(N):
        for i in range(N):
            for j in range(i + 1, N):
                regs = [region_grid[k][c] for k in range(i, j + 1)]
                seq = [regs[0]]
                for k in range(1, len(regs)):
                    if regs[k] != regs[k-1]: seq.append(regs[k])
                if len(seq) >= 3:
                    is_minimal = True
                    for start, end in [(i+1, j), (i, j-1)]:
                        sub_regs = [region_grid[k][c] for k in range(start, end + 1)]
                        sub_seq = [sub_regs[0]]
                        for k in range(1, len(sub_regs)):
                            if sub_regs[k] != sub_seq[-1]: sub_seq.append(sub_regs[k])
                        if len(sub_seq) >= 3: is_minimal = False; break
                    if is_minimal:
                        minimal_3_region_segments.append([k * N + c for k in range(i, j + 1)])

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # 1. Region clues
            for rid, clue in clues.items():
                cells = region_cells[rid]
                blacks = [c for c in cells if grid[c] == BLACK]
                unknowns = [c for c in cells if grid[c] == UNKNOWN]
                if len(blacks) > clue: return None
                if len(blacks) + len(unknowns) < clue: return None
                if len(blacks) == clue and unknowns:
                    for c in unknowns: grid[c] = WHITE; changed = True
                if len(blacks) + len(unknowns) == clue and unknowns:
                    for c in unknowns: grid[c] = BLACK; changed = True

            # 2. No adjacent blacks
            for i in range(N * N):
                if grid[i] == BLACK:
                    for n in neighbors[i]:
                        if grid[n] == BLACK: return None
                        if grid[n] == UNKNOWN: grid[n] = WHITE; changed = True
                elif grid[i] == UNKNOWN:
                    if any(grid[n] == BLACK for n in neighbors[i]):
                        grid[i] = WHITE; changed = True

            # 3. Heyawake rule
            for seg in minimal_3_region_segments:
                whites = [c for c in seg if grid[c] == WHITE]
                blacks = [c for c in seg if grid[c] == BLACK]
                unknowns = [c for c in seg if grid[c] == UNKNOWN]
                if not blacks:
                    if len(whites) == len(seg): return None
                    if len(whites) == len(seg) - 1 and unknowns:
                        grid[unknowns[0]] = BLACK; changed = True

            # 4. Connectivity (basic check: non-blacks must be connected)
            non_blacks = [i for i in range(N * N) if grid[i] != BLACK]
            if non_blacks:
