                return False
        # Check region
        reg_id = regions[r][c]
        for rr, cc in region_cells[reg_id]:
            if grid[rr][cc] == val:
                return False
        return True

    def get_candidates(r, c):
        candidates = set(range(1, n + 1))
        # Row constraints
        for j in range(n):
            if grid[r][j] is not None:
                candidates.discard(grid[r][j])
        # Column constraints
        for i in range(n):
            if grid[i][c] is not None:
                candidates.discard(grid[i][c])
        # Region constraints
        reg_id = regions[r][c]
        for rr, cc in region_cells[reg_id]:
            if grid[rr][cc] is not None:
                candidates.discard(grid[rr][cc])
        return candidates

    def find_best_cell():
        min_candidates = n + 1
        best_cell = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    candidates = get_candidates(r, c)
                    if not candidates:
                        return None, None # Dead end
                    if len(candidates) < min_candidates:
                        min_candidates = len(candidates)
                        best_cell = (r, c)
                        if min_candidates == 1:
                            return best_cell, candidates
        return best_cell, (get_candidates(*best_cell) if best_cell else None)

    def backtrack():
        cell, candidates = find_best_cell()
        if cell is None:
            # If no empty cell is found, we've solved it. 
