def get_combinations(weights, target):
    """
    Generates all possible bitmasks of cells that satisfy a target sum given weights.
    Uses recursion with pruning for efficiency.
    """
    n = len(weights)
    res = []
    suffix_sums = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_sums[i] = suffix_sums[i+1] + weights[i]

    def backtrack_comb(idx, current_sum, current_mask):
        if idx == n:
            if current_sum == target:
                res.append(current_mask)
            return

        # Pruning: if current sum exceeds target or remaining weights can't reach target
        if current_sum > target:
            return
        if current_sum + suffix_sums[idx] < target:
            return

        # Option 1: Don't include weights[idx] (cell is None)
        backtrack_comb(idx + 1, current_sum, current_mask)

        # Option 2: Include weights[idx] (cell is 'B')
        backtrack_comb(idx + 1, current_sum + weights[idx], current_mask | (1 << idx))

    backtrack_comb(0, 0, 0)
    return res

def solve(observation):
    """
    Solves the puzzle using backtracking with constraint propagation and pruning.
    """
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    # Default weights to 1..N if not provided, though they are provided here
    row_weights = observation.get('row_weights', list(range(1, len(row_targets) + 1)))
    col_weights = observation.get('col_weights', list(range(1, len(col_targets) + 1)))

    R, C = len(row_targets), len(col_targets)

    # Pre-calculate all valid configurations for each row based on column weights
    row_options = [get_combinations(col_weights, t) for t in row_targets]

    # Pre-calculate maximum possible future contribution for each column to prune search
    max_col_contrib = [[0] * C for _ in range(R + 1)]
    for r in range(R - 1, -1, -1):
        for c in range(C):
            max_col_contrib[r][c] = max_col_contrib[r+1][c] + row_weights[r]

    solution_masks = []

    def backtrack(r, current_col_sums):
        # Base case: all rows processed
        if r == R:
            # Verify all column targets are met exactly
            return all(current_col_sums[c] == col_targets[c] for c in range(C))

        # Try each valid configuration for the current row
        for mask in row_options[r]:
            new_sums = list(current_col_sums)
            possible = True

            for c in range(C):
                # If cell (r, c) is black, add row weight to column sum
                if (mask >> c) & 1:
                    new_sums[c] += row_weights[r]

                # Pruning: check if current column sum exceeds target
                if new_sums[c] > col_targets[c]:
                    possible = False
                    break

                # Pruning: check if target is still reachable with remaining row weights
                if new_sums[c] + max_col_contrib[r+1][c] < col_targets[c]:
                    possible = False
                    break

            if possible:
                solution_masks.append(mask)
                if backtrack(r + 1, new_sums):
                    return True
                solution_masks.pop()

        return False

    # Execute search
    if backtrack(0, [0] * C):
        # Convert bitmasks back to grid format
        grid = [[None for _ in range(C)] for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if (solution_masks[r] >> c) & 1:
                    grid[r][c] = 'B'
        return grid

    return "No Solution"

