    # Helper to find all valid bitmasks for a target sum given weights
    def get_combinations(weights, target):
        res = []
        n = len(weights)
        for i in range(1 << n):
            s = 0
            for j in range(n):
                if (i >> j) & 1:
                    s += weights[j]
            if s == target:
                res.append(i)
        return res

    # Precompute all possible configurations for each row and column
    # row_options[r] uses col_weights to reach row_targets[r]
    # col_options[c] uses row_weights to reach col_targets[c]
    row_options = [get_combinations(col_weights, row_targets[r]) for r in range(R)]
    col_options = [get_combinations(row_weights, col_targets[c]) for c in range(C)]

    # Constraint propagation to reduce search space
    def propagate(r_opts, c_opts):
        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    # Row to Column propagation:
                    # If all remaining row configurations for row r have the same bit at column c,
                    # then column c's configurations must match that bit at row r.
                    r_bits = { (m >> c) & 1 for m in r_opts[r] }
                    if len(r_bits) == 1:
                        bit = next(iter(r_bits))
                        orig_len = len(c_opts[c])
                        c_opts[c] = [m for m in c_opts[c] if ((m >> r) & 1) == bit]
                        if not c_opts[c]: return False # Contradiction
                        if len(c_opts[c]) < orig_len: changed = True

                    # Column to Row propagation:
                    # Symmetrically, if all column configurations for column c have the same bit at row r,
                    # then row r's configurations must match that bit at column c.
                    c_bits = { (m >> r) & 1 for m in c_opts[c] }
                    if len(c_bits) == 1:
                        bit = next(iter(c_bits))
                        orig_len = len(r_opts[r])
                        r_opts[r] = [m for m in r_opts[r] if ((m >> c) & 1) == bit]
                        if not r_opts[r]: return False # Contradiction
                        if len(r_opts[r]) < orig_len: changed = True
        return True

    # Backtracking search with MRV (Minimum Remaining Values) heuristic
    def search(r_opts, c_opts):
        if not propagate(r_opts, c_opts):
            return None

        # Check if all rows and columns are uniquely determined
        if all(len(opts) == 1 for opts in r_opts) and all(len(opts) == 1 for opts in c_opts):
            grid = [[None for _ in range(C)] for _ in range(R)]
            for r in range(R):
                mask = r_opts[r][0]
                for c in range(C):
                    if (mask >> c) & 1:
                        grid[r][c] = 'B'
            return grid

        # Pick the row or column with the fewest remaining options to branch on
        best_r, min_r_opts = -1, float('inf')
        for r in range(R):
            if 1 < len(r_opts[r]) < min_r_opts:
                min_r_opts = len(r_opts[r])
                best_r = r

        best_c, min_c_opts = -1, float('inf')
        for c in range(C):
