            must_black = row_masks[r][0]
            for m in row_masks[r][1:]: must_black &= m
            must_white = (~row_masks[r][0]) & ((1 << n) - 1)
            for m in row_masks[r][1:]: must_white &= (~m) & ((1 << n) - 1)

