        # Heuristic: branch on the row/column with the fewest remaining possibilities
        best_row = min((len(r_masks[i]), i) for i in range(R) if len(r_masks[i]) > 1)
        best_col = min((len(c_masks[j]), j) for j in range(C) if len(c_masks[j]) > 1)

