            for mask in c_masks[idx]:
                new_c = [list(m) for m in c_masks]
                new_c[idx] = [mask]
                res = backtrack([list(m) for m in r_masks], new_c)
                if res: return res
        return None

    result = backtrack(row_masks, col_masks)
    return result if result else "No Solution"

