    def backtrack(idx, rem):
        if rem == 0:
            return [tuple([0] * (n - idx))]
        if idx == n or rem < 0:
            return []
        state = (idx, rem)
        if state in memo:
            return memo[state]

        res = []
        # Option 1: Include weights[idx]
        for sub in backtrack(idx + 1, rem - weights[idx]):
            res.append((1,) + sub)
        # Option 2: Exclude weights[idx]
        for sub in backtrack(idx + 1, rem):
            res.append((0,) + sub)

        memo[state] = res
        return res

    return backtrack(0, target)

