import collections

OBSERVATION = {'data': [[None, None, None, 3, None], [4, None, None, None, None], [None, 9, None, 6, None], [None, None, None, None, 5], [None, 7, None, None, None]]}

def solve(observation):
    data = observation['data']
    n = len(data)
    clues = {}
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]

    # grid: 0 = unknown, 1 = white, 2 = black
    grid = [[0] * n for _ in range(n)]
    for r, c in clues:
        grid[r][c] = 1

    def get_visibility(r, c, current_grid):
        # Returns (min_vis, max_vis)
        vis_min = 1
        vis_max = 1
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            # Max visibility: count non-black cells
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] != 2:
                vis_max += 1
                nr += dr
                nc += dc
            # Min visibility: count white cells
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] == 1:
                vis_min += 1
                nr += dr
                nc += dc
        return vis_min, vis_max

    def is_consistent(current_grid):
        # Check clues
        for (r, c), val in clues.items():
            vis_min, vis_max = get_visibility(r, c, current_grid)
            if val < vis_min or val > vis_max:
                return False

        # Check black adjacency
        for r in range(n):
            for c in range(n):
                if current_grid[r][c] == 2:
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] == 2:
                            return False

        # Check connectivity: all white cells must be able to connect via non-black cells
        whites = [(r, c) for r in range(n) for c in range(n) if current_grid[r][c] == 1]
        if not whites: return True

        start = whites[0]
        q = collections.deque([start])
        visited = {start}
        while q:
            r, c = q.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] != 2 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

        for r, c in whites:
            if (r, c) not in visited:
                return False

        return True

    def propagate(current_grid):
        changed = True
        while changed:
            changed = False
            # Rule: Black cells cannot be adjacent
            for r in range(n):
                for c in range(n):
                    if current_grid[r][c] == 2:
                        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < n and 0 <= nc < n:
                                if current_grid[nr][nc] == 0:
                                    current_grid[nr][nc] = 1
                                    changed = True
                                elif current_grid[nr][nc] == 2:
                                    return False

            # Rule: Clue visibility
            for (r, c), val in clues.items():
                vis_min, vis_max = get_visibility(r, c, current_grid)
                if vis_max == val:
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        while 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] != 2:
                            if current_grid[nr][nc] == 0:
                                current_grid[nr][nc] = 1
                                changed = True
                            nr += dr
                            nc += dc

                if vis_min == val:
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        while 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] == 1:
                            nr += dr
                            nc += dc
                        if 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] == 0:
                            current_grid[nr][nc] = 2
                            changed = True

                # Lookahead: if marking a cell black/white violates constraints
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] != 2:
                        if current_grid[nr][nc] == 0:
                            # Try Black
                            current_grid[nr][nc] = 2
                            _, new_vis_max = get_visibility(r, c, current_grid)
                            if new_vis_max < val:
                                current_grid[nr][nc] = 1
                                changed = True
                            else:
                                current_grid[nr][nc] = 0

                            if current_grid[nr][nc] == 0:
                                # Try White
                                current_grid[nr][nc] = 1
                                new_vis_min, _ = get_visibility(r, c, current_grid)
                                if new_vis_min > val:
                                    current_grid[nr][nc] = 2
                                    changed = True
                                else:
                                    current_grid[nr][nc] = 0
                        nr += dr
                        nc += dc

            # Rule: Connectivity
            for r in range(n):
                for c in range(n):
                    if current_grid[r][c] == 0:
                        current_grid[r][c] = 2
                        if not is_consistent(current_grid):
                            current_grid[r][c] = 1
                            changed = True
                        else:
                            current_grid[r][c] = 0
        return True

    def is_fully_connected(current_grid):
        whites = [(r, c) for r in range(n) for c in range(n) if current_grid[r][c] == 1]
        if not whites: return True
        start = whites[0]
        q = collections.deque([start])
        visited = {start}
        while q:
            r, c = q.popleft()
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and current_grid[nr][nc] == 1 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(whites)

    def backtrack(current_grid):
        if not is_consistent(current_grid):
            return None

        grid_copy = [row[:] for row in current_grid]
        if not propagate(grid_copy):
            return None

        unknowns = [(r, c) for r in range(n) for c in range(n) if grid_copy[r][c] == 0]
        if not unknowns:
            if is_fully_connected(grid_copy):
                for (r, c), val in clues.items():
                    v_min, v_max = get_visibility(r, c, grid_copy)
                    if v_min != val or v_max != val:
                        return None
                return grid_copy
            return None

        r, c = unknowns[0]
        # Try White
        grid_copy[r][c] = 1
        res = backtrack(grid_copy)
        if res: return res

        # Try Black
        grid_copy[r][c] = 2
        res = backtrack(grid_copy)
        if res: return res

        return None

    final_grid = backtrack(grid)
    if not final_grid:
        return "No Solution"

    output = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if (r, c) in clues:
                output[r][c] = clues[(r, c)]
            elif final_grid[r][c] == 2:
                output[r][c] = 'B'
            else:
                output[r][c] = None
    return output

if __name__ == "__main__":
    print(solve(OBSERVATION))

