OBSERVATION = {'data': [[None, None, 5, None, None, None, 13, None, None, None], [None, None, None, None, None, None, None, None, None, 4], [None, 11, None, None, None, None, None, None, None, None], [None, None, 8, None, 11, None, 14, 6, None, None], [None, 11, None, None, None, None, None, None, 8, None], [None, 14, None, None, None, None, None, None, 17, None], [None, None, 8, 4, None, 12, None, 6, None, None], [None, None, None, None, None, None, None, None, 8, None], [11, None, None, None, None, None, None, None, None, None], [None, None, None, 2, None, None, None, 3, None, None]]}

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])
    clues = []
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                clues.append((r, c, data[r][c]))

    # grid: 0=UNKNOWN, 1=WHITE, 2=BLACK
    grid = [[0 for _ in range(C)] for _ in range(R)]
    for r, c, val in clues:
        grid[r][c] = 1

    row_clue_counts = [0] * R
    col_clue_counts = [0] * C
    for r, c, val in clues:
        row_clue_counts[r] += 1
        col_clue_counts[c] += 1

    def get_vis_limits(grid, r, c):
        L, M, cells_M = [], [], []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            l_count, m_count, m_cells = 0, 0, []
            nr, nc = r + dr, c + dc
            found_non_white = False
            while 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != 2:
                m_count += 1
                m_cells.append((nr, nc))
                if not found_non_white:
                    if grid[nr][nc] == 1:
                        l_count += 1
                    else:
                        found_non_white = True
                nr += dr
                nc += dc
            L.append(l_count)
            M.append(m_count)
            cells_M.append(m_cells)
        return L, M, cells_M

    def check_connectivity(grid):
        white_cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
        if not white_cells: return []
        start = white_cells[0]
        visited = {start}
        queue = collections.deque([start])
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != 2 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
        for wr, wc in white_cells:
            if (wr, wc) not in visited: return False
        to_black = []
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0 and (r, c) not in visited:
                    to_black.append((r, c))
        return to_black

    def propagate(grid):
        changed = True
        while changed:
            changed = False
            # Clue constraints
            for r, c, val in clues:
                L, M, cells_M = get_vis_limits(grid, r, c)
                min_vis, max_vis = 1 + sum(L), 1 + sum(M)
                if min_vis > val or max_vis < val: return False
                if max_vis == val:
                    for m_list in cells_M:
                        for mr, mc in m_list:
                            if grid[mr][mc] == 0:
                                grid[mr][mc] = 1; changed = True
                if min_vis == val:
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r, c
                        while True:
                            nr += dr; nc += dc
                            if not (0 <= nr < R and 0 <= nc < C): break
                            if grid[nr][nc] == 0:
                                grid[nr][nc] = 2; changed = True; break
                            if grid[nr][nc] == 2: break
                for d in range(4):
                    max_vis_excl_d = 1 + sum(M[i] for i in range(4) if i != d) + L[d]
                    if max_vis_excl_d < val:
                        dr, dc = [(-1, 0), (1, 0), (0, -1), (0, 1)][d]
                        nr, nc = r + dr * (L[d] + 1), c + dc * (L[d] + 1)
                        if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 0:
                            grid[nr][nc] = 1; changed = True
            # No-adjacent-black
            for r in range(R):
                for c in range(C):
                    if grid[r][c] == 2:
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C:
                                if grid[nr][nc] == 2: return False
                                if grid[nr][nc] == 0:
                                    grid[nr][nc] = 1; changed = True
            # Connectivity
            res = check_connectivity(grid)
            if res is False: return False
            for br, bc in res:
                grid[br][bc] = 2; changed = True
            # Simple articulation point rule
            white_cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
            for r, c in white_cells:
                non_black_neighbors = []
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != 2:
                        non_black_neighbors.append((nr, nc))
                if len(non_black_neighbors) == 0: return False
                if len(non_black_neighbors) == 1:
                    nr, nc = non_black_neighbors[0]
                    if grid[nr][nc] == 0:
                        grid[nr][nc] = 1; changed = True
        return True

    def backtrack(grid):
        if not propagate(grid): return None
        best_cell, max_clues = None, -1
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 0:
                    clue_count = row_clue_counts[r] + col_clue_counts[c]
                    if clue_count > max_clues:
                        max_clues, best_cell = clue_count, (r, c)
        if not best_cell:
            for r, c, val in clues:
                L, _, _ = get_vis_limits(grid, r, c)
                if 1 + sum(L) != val: return None
            return grid
        r, c = best_cell
        for val in [1, 2]:
            new_grid = [row[:] for row in grid]
            new_grid[r][c] = val
            res = backtrack(new_grid)
            if res: return res
        return None

    final_grid = backtrack(grid)
    if not final_grid: return "No Solution"
    res_data = [[None for _ in range(C)] for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if final_grid[r][c] == 2: res_data[r][c] = 'B'
            elif data[r][c] is not None: res_data[r][c] = data[r][c]
            else: res_data[r][c] = None
    return res_data

if __name__ == "__main__":
    print(solve(OBSERVATION))

