def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    # Precompute white cells and numbered black cells
    white_cells = []
    numbered_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] is None:
                white_cells.append((r, c))
            elif grid[r][c] >= 0:
                numbered_cells.append((r, c, grid[r][c]))

    def is_valid_pos(r, c):
        return 0 <= r < rows and 0 <= c < cols

    def get_neighbors(r, c):
        res = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_valid_pos(nr, nc):
                res.append((nr, nc))
        return res

    def get_illuminated(r, c, current_bulbs):
        # Returns set of cells illuminated by a bulb at (r, c)
        illuminated = {(r, c)}
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            while is_valid_pos(nr, nc) and grid[nr][nc] is None:
                illuminated.add((nr, nc))
                nr += dr
                nc += dc
        return illuminated

    def check_constraints(current_bulbs):
        # 1. No bulb may illuminate another bulb
        for b1 in current_bulbs:
            for b2 in current_bulbs:
                if b1 == b2: continue
                if b1[0] == b2[0]: # same row
                    blocked = False
                    for c in range(min(b1[1], b2[1]) + 1, max(b1[1], b2[1])):
                        if grid[b1[0]][c] is not None:
                            blocked = True
                            break
                    if not blocked: return False
                if b1[1] == b2[1]: # same col
                    blocked = False
                    for r in range(min(b1[0], b2[0]) + 1, max(b1[0], b2[0])):
                        if grid[r][b1[1]] is not None:
                            blocked = True
                            break
                    if not blocked: return False

        # 2. Numbered black cells must have exact adjacent bulbs
        for r, c, val in numbered_cells:
            count = 0
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) in current_bulbs:
                    count += 1
            if count != val:
                return False
        return True

    def is_fully_illuminated(current_bulbs):
        illuminated_set = set()
        for r, c in current_bulbs:
            illuminated_set.update(get_illuminated(r, c, current_bulbs))
        return all(cell in illuminated_set for cell in white_cells)

    # Human-like deduction: Pruning based on numbered cells
    possible_bulb_locations = set(white_cells)

    # Rule: 0-numbered cells block adjacent bulbs
    for r, c, val in numbered_cells:
        if val == 0:
            for nr, nc in get_neighbors(r, c):
                if (nr, nc) in possible_bulb_locations:
                    possible_bulb_locations.remove((nr, nc))

    # Backtracking search with pruning
    def backtrack(idx, current_bulbs):
        # Check numbered cell constraints early
        for r, c, val in numbered_cells:
            adj_white = [n for n in get_neighbors(r, c) if grid[n[0]][n[1]] is None]
            bulbs_around = sum(1 for n in get_neighbors(r, c) if n in current_bulbs)
            potential_bulbs = sum(1 for n in adj_white if n in possible_bulb_locations or n in current_bulbs)
            if bulbs_around > val: return None
            # If we can't reach the required number even if we fill all remaining white neighbors
            # This is a bit complex to track perfectly during simple recursion, so we rely on final check

        if idx == len(white_cells):
            if check_constraints(current_bulbs) and is_fully_illuminated(current_bulbs):
                return current_bulbs
            return None

        # Try placing a bulb at white_cells[idx] if it's a valid location
        cell = white_cells[idx]
        if cell in possible_bulb_locations:
            # Check if placing a bulb here violates "no bulb sees another bulb"
            can_place = True
            for b in current_bulbs:
                if b[0] == cell[0]:
                    blocked = False
                    for c in range(min(b[1], cell[1]) + 1, max(b[1], cell[1])):
                        if grid[b[0]][c] is not None: blocked = True; break
                    if not blocked: can_place = False; break
                if b[1] == cell[1]:
                    blocked = False
                    for r in range(min(b[0], cell[0]) + 1, max(b[0], cell[0])):
                        if grid[r][b[1]] is not None: blocked = True; break
                    if not blocked: can_place = False; break

            if can_place:
                res = backtrack(idx + 1, current_bulbs | {cell})
                if res: return res

        # Try not placing a bulb
        res = backtrack(idx + 1, current_bulbs)
        if res: return res

        return None

    # Optimization: Start with cells that MUST have bulbs based on numbered constraints
    # For simplicity in this generalized solver, we use a more efficient backtracking
    # that respects numbered constraints at each step.

    def solve_recursive(cell_idx, current_bulbs):
        if cell_idx == len(white_cells):
            if check_constraints(current_bulbs) and is_fully_illuminated(current_bulbs):
                return current_bulbs
            return None

        r, c = white_cells[cell_idx]

        # Try placing bulb
        if (r, c) in possible_bulb_locations:
            # Check "no bulb sees another bulb"
            sees_bulb = False
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                while is_valid_pos(nr, nc) and grid[nr][nc] is None:
                    if (nr, nc) in current_bulbs:
                        sees_bulb = True
                        break
                    nr += dr
                    nc += dc
                if sees_bulb: break

            if not sees_bulb:
                res = solve_recursive(cell_idx + 1, current_bulbs | {(r, c)})
                if res: return res

        # Try not placing bulb
        res = solve_recursive(cell_idx + 1, current_bulbs)
        return res

    solution_bulbs = solve_recursive(0, set())

    if solution_bulbs is None:
        return "No Solution"

    # Format output
    output_grid = [[None for _ in range(cols)] for _ in range(rows)]
    for r, c in solution_bulbs:
        output_grid[r][c] = 'B'
    return output_grid

