def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])

    # Identify all white cells
    white_cells = []
    for r in range(R):
        for c in range(C):
            if data[r][c] is None:
                white_cells.append((r, c))

    # Pre-calculate visibility for each white cell
    # visibility[(r, c)] is a list of all white cells that can light up (r, c)
    visibility = {}
    for r, c in white_cells:
        vis = [(r, c)]
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            while 0 <= nr < R and 0 <= nc < C and data[nr][nc] is None:
                vis.append((nr, nc))
                nr += dr
                nc += dc
        visibility[(r, c)] = vis

    # Pre-calculate numbered black cell constraints
    numbered_cells = []
    for r in range(R):
        for c in range(C):
            val = data[r][c]
            if isinstance(val, int) and val >= 0:
                neighbors = []
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C and data[nr][nc] is None:
                        neighbors.append((nr, nc))
                numbered_cells.append(((r, c), val, neighbors))

    def get_deduced_state(curr_state):
        """Applies logical deductions to prune the search space."""
        changed = True
        while changed:
            changed = False
            # 1. Numbered constraints: check if bulbs must be placed or cannot be placed
            for (r, c), val, neighbors in numbered_cells:
                bulbs = [n for n in neighbors if curr_state[n] == 'B']
                unknowns = [n for n in neighbors if curr_state[n] is None]
                if len(bulbs) > val: return None
                if len(bulbs) + len(unknowns) < val: return None
                if len(bulbs) == val and unknowns:
                    for u in unknowns:
                        curr_state[u] = '.'
                        changed = True
                if len(bulbs) + len(unknowns) == val and unknowns:
                    for u in unknowns:
                        curr_state[u] = 'B'
                        changed = True

            # 2. Bulb visibility and lit status constraints
            for rc in white_cells:
                # Check if the cell is currently lit by any bulb
                is_lit = any(curr_state[v] == 'B' for v in visibility[rc])

                if curr_state[rc] == 'B':
                    # Rule: No bulb may illuminate another bulb
                    for v in visibility[rc]:
                        if v != rc:
                            if curr_state[v] == 'B': return None
                            if curr_state[v] is None:
                                curr_state[v] = '.'
                                changed = True
                elif curr_state[rc] is None:
                    if is_lit:
                        # If already lit, it cannot be a bulb (Rule: no bulb sees another)
                        curr_state[rc] = '.'
                        changed = True
                    else:
                        # If not lit, check if there's only one way left to light it
                        possible = [v for v in visibility[rc] if curr_state[v] is None]
                        if not possible: return None
                        if len(possible) == 1:
                            curr_state[possible[0]] = 'B'
                            changed = True
                elif curr_state[rc] == '.':
                    # If marked as empty, it still must be lit eventually
                    if not is_lit:
                        possible = [v for v in visibility[rc] if curr_state[v] is None]
