    def backtrack(bulbs, forbidden, lit_count):
        if not deduce(bulbs, forbidden, lit_count):
            return None

        unlit = [wc for wc in white_cells if lit_count[wc[0]][wc[1]] == 0]
        if not unlit:
            for r, c in numbered_cells:
                if sum(1 for n in neighbors_map[(r, c)] if n in bulbs) != data[r][c]:
                    return None
            return bulbs

        # Heuristic: pick unlit cell with fewest potential bulb positions
        wc = min(unlit, key=lambda x: len([p for p in visibility[x] if p not in forbidden and lit_count[p[0]][p[1]] == 0]))
        potential = [p for p in visibility[wc] if p not in forbidden and lit_count[p[0]][p[1]] == 0]

        for p in potential:
