                if res is not None: return res
        return None

    initial_bulbs = set()
    initial_forbidden = set()
    initial_lit_count = [[0 for _ in range(C)] for _ in range(R)]

    final_bulbs = backtrack(initial_bulbs, initial_forbidden, initial_lit_count)

    if final_bulbs is None:
        return "No Solution"

    result_grid = [[None for _ in range(C)] for _ in range(R)]
    for r, c in final_bulbs:
        result_grid[r][c] = 'B'
    return result_grid

