        if not target: return None

        # Try placing a bulb
        res = backtrack(bulbs | {target}, empties)
        if res is not None: return res

        # Try marking as empty
        return backtrack(bulbs, empties | {target})

    final_bulbs = backtrack(set(), set())
    if final_bulbs is None:
        return "No Solution"

    # Construct the output grid
    result = [[None for _ in range(C)] for _ in range(R)]
    for r, c in final_bulbs:
