import collections
import itertools

# OBSERVATION represents the region mapping of the 8x8 grid.
# Each number corresponds to a unique region in the puzzle.
OBSERVATION = {'data': [
    [0, 0, 0, 0, 0, 0, 1, 1],
    [0, 2, 2, 2, 2, 3, 3, 1],
    [4, 4, 5, 5, 5, 3, 3, 1],
    [4, 4, 5, 5, 6, 3, 3, 1],
    [7, 4, 5, 5, 6, 3, 3, 8],
    [7, 7, 5, 5, 6, 3, 3, 8],
    [7, 9, 9, 9, 6, 3, 3, 8],
    [7, 9, 9, 9, 9, 3, 3, 8]
]}

def get_all_shapes():
    """Generates all rotations and reflections of L, I, T, S tetrominoes."""
    base_shapes = {
        'I': {(0,0), (0,1), (0,2), (0,3)},
        'L': {(0,0), (1,0), (2,0), (2,1)},
        'T': {(0,0), (0,1), (0,2), (1,1)},
        'S': {(0,0), (0,1), (1,1), (1,2)}
    }
    all_shapes = collections.defaultdict(set)
    for name, shape in base_shapes.items():
        for _ in range(4):
            # Rotate 90 degrees
            shape = {(c, -r) for r, c in shape}
            # Normalize to (0,0)
            min_r, min_c = min(r for r, c in shape), min(c for r, c in shape)
            normalized = frozenset((r - min_r, c - min_c) for r, c in shape)
            all_shapes[name].add(normalized)
            # Reflect and normalize
            reflected = {(-r, c) for r, c in shape}
            min_r, min_c = min(r for r, c in reflected), min(c for r, c in reflected)
            normalized = frozenset((r - min_r, c - min_c) for r, c in reflected)
            all_shapes[name].add(normalized)
    return all_shapes

def is_cells_connected(combo):
    """Checks if a set of 4 cells is orthogonally connected."""
    combo = list(combo)
    if not combo: return True
    visited = {combo[0]}
    stack = [combo[0]]
    while stack:
