    region_map = {}
    for r in range(rows):
        for c in range(cols):
            rid = data[r][c]
            if rid not in region_map: region_map[rid] = []
            region_map[rid].append((r, c))

    regions = list(region_map.values())
    rid_to_idx = {data[r[0][0]][r[0][1]]: i for i, r in enumerate(regions)}

    # Find adjacent regions
    adj_regions = [set() for _ in range(len(regions))]
    for i, region in enumerate(regions):
        for r, c in region:
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
