            min_c = min(c for r, c in curr)
            norm = tuple(sorted((r - min_r, c - min_c) for r, c in curr))
            syms.add(norm)
            # flip
            flipped = tuple((-c, r) for r, c in curr)
            min_r = min(r for r, c in flipped)
            min_c = min(c for r, c in flipped)
            norm_f = tuple(sorted((r - min_r, c - min_c) for r, c in flipped))
