    L_SHAPES = get_symmetries(((0,0), (1,0), (2,0), (2,1)))
    T_SHAPES = get_symmetries(((0,0), (0,1), (0,2), (1,1)))
    S_SHAPES = get_symmetries(((0,1), (0,2), (1,0), (1,1)))

