        min_c = min(c for r, c in cells)
        norm = tuple(sorted((r - min_r, c - min_c) for r, c in cells))
        if norm in I_SHAPES: return 'I'
        if norm in L_SHAPES: return 'L'
        if norm in T_SHAPES: return 'T'
        if norm in S_SHAPES: return 'S'
