                    self.status[e] = True
                    res = self.solve()
                    if res: return res
                    self.status = saved_status
                    self.status[e] = False
                    res = self.solve()
                    if res: return res
                    break
            return None

        def trace_path(self, start_node):
            path = [start_node]
            curr = start_node
            prev = None
            while True:
                next_node = None
                for e in self.adj[curr]:
                    if self.status[e] is True:
