                            if e1 and e2 and self.status[e1] is not False and self.status[e2] is not False:
                                if (not e1_ext or self.status[e1_ext] is not False) and (not e2_ext or self.status[e2_ext] is not False):
                                    possible_turns.append((e1, e2, e1_ext, e2_ext))

                        if not possible_turns: return False
                        if len(possible_turns) == 1:
                            e1, e2, e1_ext, e2_ext = possible_turns[0]
                            for e in [e1, e2, e1_ext, e2_ext]:
                                if e and self.status[e] is None: self.status[e] = True; changed = True

                        # If an edge is used, its extension must be used
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            e = self.get_edge((r,c), (r+dr,c+dc))
                            if e and self.status[e] is True:
                                ext = self.get_edge((r+dr,c+dc), (r+2*dr,c+2*dc))
                                if not ext: return False
                                if self.status[ext] is None: self.status[ext] = True; changed = True
                                elif self.status[ext] is False: return False

