                    if is_cycle:
                        if len(comp) < len(self.clues) or any(node in self.clues and node not in comp for node in self.clues):
                            return False
                        # If it's a valid cycle, all other edges must be False
                        for e in self.all_edges:
                            if self.status[e] is None:
                                self.status[e] = False
                                changed = True

                # Path ends cannot connect if it forms a small loop
                for comp in components:
                    ends = [node for node in comp if len([e for e in self.adj[node] if self.status[e] is True]) == 1]
                    if len(ends) == 2:
                        u, v = ends
                        e_uv = self.get_edge(u, v)
                        if e_uv and self.status[e_uv] is None:
                            # If connecting u-v forms a cycle, check if it's the final one
                            if len(comp) < len(self.clues) or any(node in self.clues and node not in comp for node in self.clues):
                                self.status[e_uv] = False
                                changed = True
            return True

        def get_components(self):
            visited = set()
            components = []
            for r in range(self.N):
                for c in range(self.N):
                    node = (r, c)
                    if node not in visited and any(self.status[e] is True for e in self.adj[node]):
                        comp = []
                        q = collections.deque([node])
                        visited.add(node)
                        while q:
                            curr = q.popleft()
                            comp.append(curr)
                            for e in self.adj[curr]:
                                if self.status[e] is True:
                                    neighbor = e[0] if e[1] == curr else e[1]
                                    if neighbor not in visited:
                                        visited.add(neighbor)
                                        q.append(neighbor)
                        components.append(comp)
            return components

        def solve(self):
            if not self.propagate(): return None

            # Check if complete
            components = self.get_components()
            if len(components) == 1:
                comp = components[0]
                if all(len([e for e in self.adj[node] if self.status[e] is True]) == 2 for node in comp):
                    if all(clue in comp for clue in self.clues):
                        return self.trace_path(comp[0])

            # Backtrack
            for e in self.all_edges:
                if self.status[e] is None:
                    saved_status = self.status.copy()
                    self.status[e] = True
                    res = self.solve()
                    if res: return res
                    self.status = saved_status
                    self.status[e] = False
                    res = self.solve()
                    if res: return res
                    break
            return None

        def trace_path(self, start_node):
            path = [start_node]
            curr = start_node
            prev = None
            while True:
                next_node = None
                for e in self.adj[curr]:
                    if self.status[e] is True:
                        neighbor = e[0] if e[1] == curr else e[1]
                        if neighbor != prev:
                            next_node = neighbor
                            break
                if next_node == start_node or next_node is None:
                    path.append(start_node)
                    break
                path.append(next_node)
                prev, curr = curr, next_node
            return path

    solver = MasyuSolver(N, clues, all_edges)
    return solver.solve()

