                        if 0 <= nr < rows and 0 <= nc < cols and data[nr][nc] is None:
                            cells.append((nr, nc))
                if cells:
                    initial_constraints.append({'cells': frozenset(cells), 'count': data[r][c]})
                elif data[r][c] > 0:
