            added = []
            sorted_cons = sorted(constraints, key=lambda x: len(x['cells']))
            for i in range(len(sorted_cons)):
                for j in range(i + 1, len(sorted_cons)):
                    c1, c2 = sorted_cons[i], sorted_cons[j]
                    if c1['cells'].issubset(c2['cells']):
