def get_configs(length, clues):
    """Generates all possible valid configurations for a line of given length and clues."""
    memo = {}

    def rec(l, c_idx):
        if (l, c_idx) in memo:
            return memo[(l, c_idx)]
        if c_idx == len(clues):
            return [[2] * l]  # 2 represents empty (None)

        res = []
        min_needed = sum(clues[c_idx:]) + len(clues) - c_idx - 1
        for start in range(l - min_needed + 1):
            prefix = [2] * start + [1] * clues[c_idx]  # 1 represents black ('B')
            if c_idx == len(clues) - 1:
                res.append(prefix + [2] * (l - len(prefix)))
            else:
                # Must have at least one empty cell after a run
                for suffix in rec(l - len(prefix) - 1, c_idx + 1):
                    res.append(prefix + [2] + suffix)

        memo[(l, c_idx)] = res
        return res

    return rec(length, 0)

def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    R, C = len(row_clues), len(col_clues)

    # Precompute all possible configurations for each row and column
    row_configs = [get_configs(C, clues) for clues in row_clues]
    col_configs = [get_configs(R, clues) for clues in col_clues]

    # Initial grid: 0 for unknown, 1 for black ('B'), 2 for empty (None)
    grid = [[0] * C for _ in range(R)]

    def backtrack(curr_grid, r_cfgs, c_cfgs):
        # Create local copies for this branch of search
        curr_grid = [row[:] for row in curr_grid]
        r_cfgs = [list(cfgs) for cfgs in r_cfgs]
        c_cfgs = [list(cfgs) for cfgs in c_cfgs]

        # Constraint Propagation Loop
        while True:
            changed = False

            # Filter row configurations and propagate
            for r in range(R):
                r_cfgs[r] = [cfg for cfg in r_cfgs[r] if all(curr_grid[r][c] == 0 or curr_grid[r][c] == cfg[c] for c in range(C))]
                if not r_cfgs[r]: return None
                for c in range(C):
                    if curr_grid[r][c] == 0:
                        vals = {cfg[c] for cfg in r_cfgs[r]}
                        if len(vals) == 1:
                            curr_grid[r][c] = list(vals)[0]
                            changed = True

            # Filter column configurations and propagate
            for c in range(C):
                c_cfgs[c] = [cfg for cfg in c_cfgs[c] if all(curr_grid[r][c] == 0 or curr_grid[r][c] == cfg[r] for r in range(R))]
                if not c_cfgs[c]: return None
                for r in range(R):
                    if curr_grid[r][c] == 0:
                        vals = {cfg[r] for cfg in c_cfgs[c]}
                        if len(vals) == 1:
                            curr_grid[r][c] = list(vals)[0]
                            changed = True

            if not changed: break

        # Check if solved
        if all(all(cell != 0 for cell in row) for row in curr_grid):
            return curr_grid

        # Backtracking: Pick an unknown cell with the fewest options (MRV heuristic)
        best_cell = None
        min_options = 3
        for r in range(R):
            for c in range(C):
                if curr_grid[r][c] == 0:
                    row_vals = {cfg[c] for cfg in r_cfgs[r]}
                    col_vals = {cfg[r] for cfg in c_cfgs[c]}
                    common = row_vals.intersection(col_vals)
                    if not common: return None
                    if len(common) < min_options:
                        min_options = len(common)
                        best_cell = (r, c, common)

        if not best_cell: return None

        r, c, options = best_cell
        for val in sorted(list(options)):
            curr_grid[r][c] = val
            res = backtrack(curr_grid, r_cfgs, c_cfgs)
            if res: return res

        return None

    final_grid = backtrack(grid, row_configs, col_configs)
    if final_grid:
        return [[('B' if cell == 1 else None) for cell in row] for row in final_grid]
    return "No Solution"

