    num_cols = len(col_clues)

    memo = {}

    def get_configs(clues, length):
        clues = tuple(clues)
        if (clues, length) in memo:
            return memo[(clues, length)]

        if not clues:
            res = ((-1,) * length,) if length >= 0 else ()
            memo[(clues, length)] = res
            return res

        min_needed = sum(clues) + len(clues) - 1
        if length < min_needed:
            memo[(clues, length)] = ()
            return ()

        res = []
        c0 = clues[0]
        # Minimum space needed for the remaining clues
        min_room_for_rest = sum(clues[1:]) + len(clues[1:]) if len(clues) > 1 else 0

        # Try all possible starting positions for the first clue
        for s in range(length - min_room_for_rest - c0 + 1):
            prefix = (-1,) * s + (1,) * c0
            if len(clues) > 1:
                # Must have at least one empty cell after a run
                for suffix in get_configs(clues[1:], length - s - c0 - 1):
                    res.append(prefix + (-1,) + suffix)
            else:
                # Pad the rest with empty cells
                res.append(prefix + (-1,) * (length - len(prefix)))

        res = tuple(res)
        memo[(clues, length)] = res
        return res

