    row_poss = [list(get_configs(clues, num_cols)) for clues in row_clues]
    col_poss = [list(get_configs(clues, num_rows)) for clues in col_clues]

    # Grid: 0 = unknown, 1 = black, -1 = empty
    grid = [[0 for _ in range(num_cols)] for _ in range(num_rows)]

    def propagate(g, r_poss, c_poss):
        changed = True
        while changed:
            changed = False
            # Update rows based on current grid state
            for r in range(num_rows):
                new_poss = [p for p in r_poss[r] if all(g[r][c] == 0 or g[r][c] == p[c] for c in range(num_cols))]
                if not new_poss: return False
                if len(new_poss) < len(r_poss[r]):
                    r_poss[r] = new_poss
                    changed = True

                # Find cells that must be black or empty in all remaining configurations
                for c in range(num_cols):
                    if g[r][c] == 0:
                        val = new_poss[0][c]
                        if all(p[c] == val for p in new_poss):
                            g[r][c] = val
                            changed = True

            # Update columns based on current grid state
            for c in range(num_cols):
                new_poss = [p for p in c_poss[c] if all(g[r][c] == 0 or g[r][c] == p[r] for r in range(num_rows))]
                if not new_poss: return False
