                n_idx = nr * N + nc
                # Optimization: only pair with a neighbor that hasn't been processed yet
                if n_idx > idx and grid[nr][nc] == 0:
                    n_reg_id = grid_data[nr][nc]
                    # Check if both regions can accommodate another shaded cell
                    if region_shaded_count[n_reg_id] < (2 if n_reg_id != reg_id else 1):
                        # Potential domino ((r,c), (nr,nc))
                        # Rule: Different dominoes cannot touch orthogonally
                        # All neighbors of the domino (except the partner) must be EMPTY
                        forbidden_all = set()
                        for fr, fc in get_neighbors(r, c):
                            if (fr, fc) != (nr, nc): forbidden_all.add((fr, fc))
                        for fr, fc in get_neighbors(nr, nc):
