        # Pruning: can we still get 2 shaded cells in this region?
        if region_shaded_count[reg_id] + region_remaining_cells[reg_id] - 1 >= 2:
            grid[r][c] = 2
            region_remaining_cells[reg_id] -= 1
            if backtrack(idx + 1):
                return True
            # Undo
            region_remaining_cells[reg_id] += 1
            grid[r][c] = 0

        return False

    if backtrack(0):
        return [[('S' if grid[r][c] == 1 else None) for c in range(N)] for r in range(N)]
