            new_state[r][c] = 2
            res = backtrack(new_state)
            if res: return res
            # Try Shaded (must try all partners)
            for nr, nc in get_neighbors(r, c):
                if state[nr][nc] == 0:
                    res = backtrack(set_domino(state, r, c, nr, nc))
                    if res: return res
            return None

    # Initial state: 0=Unknown, 1=Shaded, 2=Empty
    initial_state = [[0 for _ in range(size)] for _ in range(size)]
    final_state = backtrack(initial_state)

    if not final_state: return "No Solution"

    # Format output
    return [[('S' if final_state[r][c] == 1 else None) for c in range(size)] for r in range(size)]

