    grid_data = observation['data']
    N = len(grid_data)
    region_map = grid_data

    # Pre-process regions
    regions = {}
    for r in range(N):
        for c in range(N):
            rid = region_map[r][c]
            if rid not in regions:
                regions[rid] = []
            regions[rid].append((r, c))

    region_ids = sorted(regions.keys())
    num_regions = len(region_ids)

    # State
    grid = [[None for _ in range(N)] for _ in range(N)]
    region_counts = {rid: 0 for rid in region_ids}
    unassigned_in_region = {rid: len(regions[rid]) for rid in region_ids}

    def get_neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def can_place_domino(r1, c1, r2, c2):
        reg1, reg2 = region_map[r1][c1], region_map[r2][c2]
        # Region count check
        if reg1 == reg2:
            if region_counts[reg1] != 0: return False
        else:
            if region_counts[reg1] >= 2 or region_counts[reg2] >= 2: return False

        # No touching rule: check neighbors of (r1, c1) and (r2, c2)
        for nr, nc in get_neighbors(r1, c1):
            if (nr, nc) != (r2, c2) and grid[nr][nc] == 'S': return False
        for nr, nc in get_neighbors(r2, c2):
            if (nr, nc) != (r1, c1) and grid[nr][nc] == 'S': return False
        return True

    def is_consistent():
        for rid in region_ids:
            if region_counts[rid] + unassigned_in_region[rid] < 2:
                return False
        return True

    def backtrack():
        # Find first incomplete region
        target_rid = -1
        for rid in region_ids:
            if region_counts[rid] < 2:
                target_rid = rid
                break

        if target_rid == -1:
            return [row[:] for row in grid]

        # Find first unassigned cell in this region
        for r, c in regions[target_rid]:
            if grid[r][c] is None:
                # Option 1: Try setting (r, c) to EMPTY
                grid[r][c] = '.'
                unassigned_in_region[target_rid] -= 1
                if is_consistent():
                    res = backtrack()
                    if res: return res
                # Backtrack
                grid[r][c] = None
                unassigned_in_region[target_rid] += 1

                # Option 2: Try setting (r, c) to SHADED (must form a domino)
                for nr, nc in get_neighbors(r, c):
                    if grid[nr][nc] is None and can_place_domino(r, c, nr, nc):
                        # Place domino
                        nreg = region_map[nr][nc]
                        grid[r][c] = 'S'
                        grid[nr][nc] = 'S'
                        region_counts[target_rid] += 1
                        region_counts[nreg] += 1
                        unassigned_in_region[target_rid] -= 1
                        unassigned_in_region[nreg] -= 1

                        if is_consistent():
                            res = backtrack()
                            if res: return res

                        # Backtrack
                        grid[r][c] = None
                        grid[nr][nc] = None
                        region_counts[target_rid] -= 1
                        region_counts[nreg] -= 1
