def get_neighbors(r, c, R, C):
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < R and 0 <= nc < C:
            yield nr, nc

def get_component(grid, start_pos, value, R, C):
    r, c = start_pos
    if grid[r][c] != value: return set()
    q = [start_pos]
    comp = {start_pos}
    idx = 0
    while idx < len(q):
        curr_r, curr_c = q[idx]
        idx += 1
        for nr, nc in get_neighbors(curr_r, curr_c, R, C):
            if grid[nr][nc] == value and (nr, nc) not in comp:
                comp.add((nr, nc))
                q.append((nr, nc))
    return comp

def get_components(grid, value, R, C):
    visited = set()
    comps = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] == value and (r, c) not in visited:
                comp = get_component(grid, (r, c), value, R, C)
                visited.update(comp)
                comps.append(comp)
    return comps

def get_reachable(grid, start_set, allowed_values, R, C):
    reachable = set(start_set)
    q = list(start_set)
    idx = 0
    while idx < len(q):
        r, c = q[idx]
        idx += 1
        for nr, nc in get_neighbors(r, c, R, C):
