        r, c = q[idx]
        idx += 1
        for nr, nc in get_neighbors(r, c, R, C):
            if (nr, nc) in allowed_set and (nr, nc) not in reachable:
                reachable.add((nr, nc))
                q.append((nr, nc))
    return reachable

