    for r in range(R - 1):
        for c in range(C - 1):
            if all(grid[r + dr][c + dc] == 2 for dr, dc in [(0, 0), (0, 1), (1, 0), (1, 1)]): return False
    white_comps = get_components(grid, 1, R, C)
    if len(white_comps) != len(roots): return False
    for comp in white_comps:
        roots_in_comp = [root for root in roots if root in comp]
        if len(roots_in_comp) != 1: return False
        if len(comp) != target_sizes[roots_in_comp[0]]: return False
