import collections
import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    dots = set(tuple(d) for d in observation['adjacent'])

    # Initialize domains
    domains = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, N + 1))

    # Define constraints
    # A constraint is a tuple (u, v, type, has_dot)
    # type: 'sudoku' (u != v), 'adjacency' (abs(u-v)==1 if has_dot else abs(u-v)!=1)
    constraints = []

    # Sudoku constraints: same row/column must be different
    for i in range(N):
        for j1 in range(N):
            for j2 in range(j1 + 1, N):
                # Row constraints
                constraints.append(((i, j1), (i, j2), 'sudoku', None))
                constraints.append(((i, j2), (i, j1), 'sudoku', None))
                # Column constraints
                constraints.append(((j1, i), (j2, i), 'sudoku', None))
                constraints.append(((j2, i), (j1, i), 'sudoku', None))

    # Adjacency constraints: consecutive if dot, non-consecutive if no dot
    for r in range(N):
        for c in range(N):
            # Horizontal adjacency
            if c + 1 < N:
                has_dot = (float(r), c + 0.5) in dots
                constraints.append(((r, c), (r, c + 1), 'adjacency', has_dot))
                constraints.append(((r, c + 1), (r, c), 'adjacency', has_dot))
            # Vertical adjacency
            if r + 1 < N:
                has_dot = (r + 0.5, float(c)) in dots
                constraints.append(((r, c), (r + 1, c), 'adjacency', has_dot))
                constraints.append(((r + 1, c), (r, c), 'adjacency', has_dot))

    def is_satisfied(val_u, val_v, c_type, has_dot):
        if c_type == 'sudoku':
            return val_u != val_v
        elif c_type == 'adjacency':
            if has_dot:
                return abs(val_u - val_v) == 1
            else:
                # Orthogonally adjacent cells must also be different (Sudoku rule)
                return val_u != val_v and abs(val_u - val_v) != 1
        return True

    def ac3(current_domains):
        queue = collections.deque(constraints)
        while queue:
            u, v, c_type, has_dot = queue.popleft()
            if revise(current_domains, u, v, c_type, has_dot):
                if not current_domains[u]:
                    return False
                # Add all constraints where u is the second variable back to queue
                for c in constraints:
                    if c[1] == u:
                        queue.append(c)
        return True

    def revise(current_domains, u, v, c_type, has_dot):
        revised = False
        to_remove = set()
        for val_u in current_domains[u]:
            if not any(is_satisfied(val_u, val_v, c_type, has_dot) for val_v in current_domains[v]):
                to_remove.add(val_u)
                revised = True
        current_domains[u] -= to_remove
        return revised

    def backtrack(current_domains):
        if not ac3(current_domains):
            return None

        # Check if solved
        if all(len(current_domains[cell]) == 1 for cell in current_domains):
            res = [[0]*N for _ in range(N)]
            for (r, c), vals in current_domains.items():
                res[r][c] = list(vals)[0]
            return res

        # MRV heuristic
        unassigned = [cell for cell in current_domains if len(current_domains[cell]) > 1]
        cell = min(unassigned, key=lambda x: len(current_domains[x]))

        for val in sorted(current_domains[cell]):
            new_domains = copy.deepcopy(current_domains)
            new_domains[cell] = {val}
            result = backtrack(new_domains)
            if result:
                return result
        return None

    solution = backtrack(domains)
    return solution if solution else "No Solution"

