        for i in range(N):
            if i != c and grid[r][i] is not None:
                possible.discard(grid[r][i])
            if i != r and grid[i][c] is not None:
                possible.discard(grid[i][c])

        # Kropki constraints
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
