                    else:
                        # Must NOT be consecutive
                        possible = {v for v in possible if abs(v - neighbor_val) != 1}
        return possible

    def backtrack(grid):
        # Find empty cell with minimum remaining values (MRV)
        best_cell = None
        min_domain = None

        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    domain = get_domain(r, c, grid)
                    if not domain:
                        return None
                    if min_domain is None or len(domain) < len(min_domain):
                        min_domain = domain
                        best_cell = (r, c)

        if best_cell is None:
            return grid

        r, c = best_cell
        for val in sorted(min_domain):
