import copy

def solve(observation):
    data = observation['data']
    N = len(data)
    adjacent_clues = observation['adjacent']

    # Parse dots into a set of frozensets for easy lookup
    dots = set()
    for r, c in adjacent_clues:
        if c % 1 != 0: # Horizontal dot
            dots.add(frozenset([(int(r), int(c)), (int(r), int(c) + 1)]))
        elif r % 1 != 0: # Vertical dot
            dots.add(frozenset([(int(r), int(c)), (int(r) + 1, int(c))]))

    # Initialize domains
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    def get_constraints(p1):
        r1, c1 = p1
        constraints = []
        # Row and Column constraints (Sudoku)
        for i in range(N):
            if i != c1: constraints.append((r1, i))
            if i != r1: constraints.append((i, c1))
        return list(set(constraints))

    def check_constraint(p1, v1, p2, v2):
        r1, c1 = p1
        r2, c2 = p2
        # Sudoku rule: same row or column must have different values
        if v1 == v2:
            return False
        # Kropki rule: orthogonally adjacent cells
        if abs(r1 - r2) + abs(c1 - c2) == 1:
            has_dot = frozenset([p1, p2]) in dots
            if has_dot:
                return abs(v1 - v2) == 1
            else:
                return abs(v1 - v2) != 1
        return True

    def propagate(domains):
        queue = []
        for r in range(N):
            for c in range(N):
                p1 = (r, c)
                for p2 in get_constraints(p1):
                    queue.append((p1, p2))

        while queue:
            p1, p2 = queue.pop(0)
            r1, c1 = p1
            r2, c2 = p2

            # Revise domain of p1 based on p2
            new_domain = set()
            changed = False
            for v1 in domains[r1][c1]:
                if any(check_constraint(p1, v1, p2, v2) for v2 in domains[r2][c2]):
                    new_domain.add(v1)
                else:
                    changed = True

            if changed:
                if not new_domain:
                    return False
                domains[r1][c1] = new_domain
                for p3 in get_constraints(p1):
                    if p3 != p2:
                        queue.append((p3, p1))
        return True

    def is_solved(domains):
        return all(len(domains[r][c]) == 1 for r in range(N) for c in range(N))

    def backtrack(domains):
        if not propagate(domains):
            return None
        if is_solved(domains):
            return [[list(domains[r][c])[0] for c in range(N)] for r in range(N)]

        # MRV heuristic
        min_options = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if len(domains[r][c]) > 1:
                    if len(domains[r][c]) < min_options:
                        min_options = len(domains[r][c])
                        best_cell = (r, c)

        if best_cell:
            r, c = best_cell
            for val in sorted(list(domains[r][c])):
                new_domains = copy.deepcopy(domains)
                new_domains[r][c] = {val}
                result = backtrack(new_domains)
                if result:
                    return result
        return None

    solution = backtrack(domains)
    return solution

