        [None, None, None, None, None, None, None],
        [None, None, None, None, None, None, None]
    ],
    'adjacent': [
        [0, 3.5], [0.5, 3], [1, 2.5], [2, 5.5], [2.5, 1], [3, 1.5],
        [3.5, 2], [3.5, 4], [4, 0.5], [4, 3.5], [4, 5.5], [4.5, 3],
        [5, 1.5], [5, 4.5], [6, 2.5]
    ]
}

def solve(observation):
    grid_data = observation['data']
    dots = set(tuple(d) for d in observation['adjacent'])
    N = len(grid_data)

    # Pre-calculate all possible adjacent pairs
    all_adj = []
    for r in range(N):
        for c in range(N):
            if c + 1 < N:
                all_adj.append(((r, c), (r, c + 1), (r, c + 0.5)))
            if r + 1 < N:
                all_adj.append(((r, c), (r + 1, c), (r + 0.5, c)))

    # Initialize domains
    domains = [[set(range(1, N + 1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if grid_data[r][c] is not None:
                domains[r][c] = {grid_data[r][c]}

    def get_neighbors(r, c):
        res = []
        if r > 0: res.append((r - 1, c, r - 0.5, c))
        if r < N - 1: res.append((r + 1, c, r + 0.5, c))
        if c > 0: res.append((r, c - 1, r, c - 0.5))
        if c < N - 1: res.append((r, c + 1, r, c + 0.5))
        return res

    def propagate():
        changed = True
        while changed:
            changed = False
            # Sudoku constraints
            for i in range(N):
                # Rows
                row_vals = [list(domains[i][j])[0] for j in range(N) if len(domains[i][j]) == 1]
                for j in range(N):
                    if len(domains[i][j]) > 1:
                        new_domain = domains[i][j] - set(row_vals)
                        if new_domain != domains[i][j]:
                            domains[i][j] = new_domain
                            changed = True
                            if not domains[i][j]: return False
                # Columns
                col_vals = [list(domains[j][i])[0] for j in range(N) if len(domains[j][i]) == 1]
                for j in range(N):
                    if len(domains[j][i]) > 1:
                        new_domain = domains[j][i] - set(col_vals)
                        if new_domain != domains[j][i]:
                            domains[j][i] = new_domain
                            changed = True
                            if not domains[j][i]: return False

            # Kropki constraints
            for (r1, c1), (r2, c2), mid in all_adj:
                is_consecutive = mid in dots
                # Propagate from 1 to 2
                new_dom2 = set()
                for v1 in domains[r1][c1]:
                    for v2 in domains[r2][c2]:
                        if (abs(v1 - v2) == 1) == is_consecutive:
                            new_dom2.add(v2)
                if new_dom2 != domains[r2][c2]:
                    domains[r2][c2] = new_dom2
                    changed = True
                    if not domains[r2][c2]: return False
                # Propagate from 2 to 1
                new_dom1 = set()
                for v2 in domains[r2][c2]:
                    for v1 in domains[r1][c1]:
                        if (abs(v1 - v2) == 1) == is_consecutive:
                            new_dom1.add(v1)
                if new_dom1 != domains[r1][c1]:
                    domains[r1][c1] = new_dom1
                    changed = True
                    if not domains[r1][c1]: return False
        return True

    def is_valid(r, c, v):
        # Row and column check
        for i in range(N):
            if i != c and grid[r][i] == v: return False
            if i != r and grid[i][c] == v: return False
        # Kropki check
        for nr, nc, mr, mc in get_neighbors(r, c):
            nv = grid[nr][nc]
            if nv != 0:
                is_consecutive = (mr, mc) in dots
                if (abs(v - nv) == 1) != is_consecutive:
                    return False
        return True

    grid = [[0] * N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) == 1:
                grid[r][c] = list(domains[r][c])[0]

    def backtrack():
        # Find cell with minimum domain size
        min_options = N + 1
        best_cell = None
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 0:
                    if len(domains[r][c]) < min_options:
                        min_options = len(domains[r][c])
                        best_cell = (r, c)

        if not best_cell:
            return True

        r, c = best_cell
        original_domains = [row[:] for row in domains]

        # Sort values by some heuristic if needed, here just iterate
        for val in sorted(list(domains[r][c])):
            if is_valid(r, c, val):
                grid[r][c] = val
                domains[r][c] = {val}
                if propagate():
                    if backtrack():
                        return True
                # Restore domains and grid
                grid[r][c] = 0
                for i in range(N): domains[i] = original_domains[i][:]
        return False

    if propagate() and backtrack():
        return grid
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

