    ],
    'adjacent': [
        # Horizontal dots (row, col+0.5)
        [0, 1.5], [0, 6.5], [0, 7.5],
        [1, 1.5], [1, 4.5], [1, 8.5],
        [2, 3.5], [2, 7.5],
