        [2.5, 2],
        [3.5, 0], [3.5, 3], [3.5, 4],
        [4.5, 1], [4.5, 5], [4.5, 6],
        [5.5, 1], [5.5, 4],
        [6.5, 0], [6.5, 2], [6.5, 8],
        [7.5, 1], [7.5, 4], [7.5, 6]
    ]
}

def solve(observation):
    grid_size = 9
    data = observation['data']
    adjacent = observation['adjacent']

    # Build adjacency constraints
    adj_map = collections.defaultdict(set)
    for r, c_mid in adjacent:
        if isinstance(c_mid, float): # Horizontal dot
            c1, c2 = int(c_mid - 0.5), int(c_mid + 0.5)
            adj_map[(r, c1)].add((r, c2))
            adj_map[(r, c2)].add((r, c1))
    for r_mid, c in adjacent:
        if isinstance(r_mid, float): # Vertical dot
            r1, r2 = int(r_mid - 0.5), int(r_mid + 0.5)
            adj_map[(r1, c)].add((r2, c))
            adj_map[(r2, c)].add((r1, c))

    # Initialize domains
    domains = {}
    for r in range(grid_size):
        for c in range(grid_size):
            if data[r][c] is not None:
                domains[(r, c)] = {data[r][c]}
            else:
                domains[(r, c)] = set(range(1, grid_size + 1))

    def get_neighbors(r, c):
        res = []
        if r > 0: res.append((r - 1, c))
        if r < grid_size - 1: res.append((r + 1, c))
        if c > 0: res.append((r, c - 1))
        if c < grid_size - 1: res.append((r, c + 1))
        return res

    def propagate(domains):
        changed = True
        while changed:
            changed = False
            # Sudoku constraints (row, col)
            for r in range(grid_size):
                for c in range(grid_size):
                    if len(domains[(r, c)]) == 1:
                        val = next(iter(domains[(r, c)]))
                        # Row
                        for c2 in range(grid_size):
                            if c2 != c and val in domains[(r, c2)]:
                                domains[(r, c2)].remove(val)
                                if not domains[(r, c2)]: return None
                                changed = True
                        # Col
                        for r2 in range(grid_size):
                            if r2 != r and val in domains[(r2, c)]:
                                domains[(r2, c)].remove(val)
                                if not domains[(r2, c)]: return None
                                changed = True

            # Kropki constraints
            for r in range(grid_size):
                for c in range(grid_size):
                    for nr, nc in get_neighbors(r, c):
                        is_adj = (nr, nc) in adj_map[(r, c)]
                        new_domain = set()
                        for v in domains[(r, c)]:
                            possible = False
                            for nv in domains[(nr, nc)]:
                                if is_adj:
                                    if abs(v - nv) == 1:
                                        possible = True
                                        break
                                else:
                                    if abs(v - nv) != 1:
                                        possible = True
                                        break
                            if possible:
                                new_domain.add(v)
                        if len(new_domain) != len(domains[(r, c)]):
                            domains[(r, c)] = new_domain
                            if not domains[(r, c)]: return None
                            changed = True
        return domains

    def backtrack(domains):
        domains = propagate(domains)
        if domains is None: return None

        if all(len(domains[cell]) == 1 for cell in domains):
            return [[next(iter(domains[(r, c)])) for c in range(grid_size)] for r in range(grid_size)]

        # Heuristic: cell with smallest domain
        cell = min((c for c in domains if len(domains[c]) > 1), key=lambda c: len(domains[c]))
        for val in sorted(domains[cell]):
            new_domains = {c: set(d) for c, d in domains.items()}
            new_domains[cell] = {val}
            res = backtrack(new_domains)
            if res: return res
        return None

    result = backtrack(domains)
    return result if result else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

