                    queue.append(((i, j2), (i, j1)))
                    queue.append(((j1, i), (j2, i)))
                    queue.append(((j2, i), (j1, i)))
        # Adjacency arcs
        for r in range(N):
            for c in range(N):
                for nr, nc in get_neighbors(r, c):
                    if ((r, c), (nr, nc)) not in queue:
                        queue.append(((r, c), (nr, nc)))

