                revised = True
        domains[(r1, c1)] -= to_remove
        return revised

    def backtrack(domains):
        if all(len(domains[cell]) == 1 for cell in domains):
            return [[list(domains[(r, c)])[0] for c in range(N)] for r in range(N)]

        # MRV heuristic
        unassigned = [cell for cell in domains if len(domains[cell]) > 1]
        cell = min(unassigned, key=lambda c: len(domains[c]))
        r, c = cell

        for val in sorted(domains[cell]):
            new_domains = {k: v.copy() for k, v in domains.items()}
            new_domains[cell] = {val}

