import collections

# The puzzle is a variation of Masyu with numbers.
# Rules:
# 1. Draw a single closed loop through dots.
# 2. No crossings or branches.
# 3. Loop must pass through all clue circles.
# 4. White circle (Wk): Loop goes straight through. Sum of lengths of the two straight segments = k.
# 5. Black circle (Bk): Loop turns at the circle. Sum of lengths of the two straight segments = k.

OBSERVATION = {
    'data': [
        [None, None, 'W4', None, None, None, None, None, None, None, 'B12'],
        [None, None, None, 'B5', None, 'B2', 'B4', 'B2', None, None, None],
        [None, None, None, None, None, 'B3', None, None, None, None, None],
        [None, 'B2', None, 'B3', None, None, None, None, None, None, None],
        ['W3', None, None, 'B3', None, None, None, None, 'W2', None, None],
        [None, 'B2', 'B5', 'B3', None, None, 'B7', None, None, 'W5', None],
        [None, None, None, None, None, 'B3', None, None, 'W2', None, None],
        [None, None, None, None, None, 'B3', None, None, None, None, None],
        [None, None, None, None, None, 'B3', None, None, None, 'W2', 'B3'],
        [None, 'B2', None, None, None, None, None, 'B4', None, None, None],
        [None, 'W4', None, None, None, None, None, None, None, None, None]
    ]
}

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    clues = []
    clue_dots = set()
    for r in range(N + 1):
        for c in range(N + 1):
            if data[r][c]:
                clues.append(((r, c), data[r][c][0], int(data[r][c][1:])))
                clue_dots.add((r, c))

    def get_edge(p1, p2):
        return tuple(sorted((p1, p2)))

    def get_neighbors(p):
        r, c = p
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr <= N and 0 <= nc <= N:
                yield (nr, nc)

    def get_clue_configs(pos, type, k):
        r, c = pos
        configs = []
        dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        if type == 'W':
            # Opposite directions
            for dr, dc in [(0, 1), (1, 0)]:
                d1, d2 = (dr, dc), (-dr, -dc)
                for L1 in range(1, k):
                    L2 = k - L1
                    config = {'true': set(), 'false': set()}
                    valid = True
