                        p_end1 = (r + L1*d1[0], c + L1*d1[1])
                        config['false'].add(get_edge(p_end1, (p_end1[0]+d1[0], p_end1[1]+d1[1])))

                        # Segment 2
                        for i in range(1, L2 + 1):
                            p1, p2 = (r + (i-1)*d2[0], c + (i-1)*d2[1]), (r + i*d2[0], c + i*d2[1])
                            if not (0 <= p2[0] <= N and 0 <= p2[1] <= N): valid = False; break
                            config['true'].add(get_edge(p1, p2))
                            if i < L2:
                                for nd in [(d2[1], d2[0]), (-d2[1], -d2[0])]:
                                    config['false'].add(get_edge(p2, (p2[0]+nd[0], p2[1]+nd[1])))
                        if not valid: continue
                        p_end2 = (r + L2*d2[0], c + L2*d2[1])
                        config['false'].add(get_edge(p_end2, (p_end2[0]+d2[0], p_end2[1]+d2[1])))

                        # Turn at clue dot
                        config['false'].add(get_edge(pos, (r-d1[0], c-d1[1])))
                        config['false'].add(get_edge(pos, (r-d2[0], c-d2[1])))

                        configs.append(config)
        return configs

    clue_configs = {pos: get_clue_configs(pos, t, k) for pos, t, k in clues}
    sorted_clues = sorted(clues, key=lambda c: len(clue_configs[c[0]]))

    def propagate(true_edges, false_edges):
        while True:
            added = False
            degrees = collections.defaultdict(int)
            for p1, p2 in true_edges:
                degrees[p1] += 1
                degrees[p2] += 1

            for r in range(N + 1):
                for c in range(N + 1):
                    p = (r, c)
                    deg = degrees[p]
                    if deg > 2: return None, None

                    if p in clue_dots or deg > 0:
                        possible = [n for n in get_neighbors(p) if get_edge(p, n) not in false_edges]
                        if len(possible) < 2: return None, None
                        if len(possible) == 2:
                            for n in possible:
                                e = get_edge(p, n)
                                if e not in true_edges:
                                    true_edges.add(e)
                                    added = True
                        if deg == 2:
                            for n in get_neighbors(p):
                                e = get_edge(p, n)
                                if e not in true_edges and e not in false_edges:
                                    false_edges.add(e)
                                    added = True

            # Subloop check
            if true_edges:
                adj = collections.defaultdict(list)
                for p1, p2 in true_edges:
                    adj[p1].append(p2)
                    adj[p2].append(p1)

                visited = set()
                for start_node in list(adj.keys()):
                    if start_node in visited: continue
                    path = []
                    curr, prev = start_node, None
                    while curr not in visited:
                        visited.add(curr)
                        path.append(curr)
                        next_nodes = [n for n in adj[curr] if n != prev]
                        if not next_nodes: break
                        prev, curr = curr, next_nodes[0]
                        if curr == start_node: # Cycle!
                            if len(path) < len(clue_dots) or len(visited) < len(adj):
                                # Check if this cycle contains all clues and all active dots
                                if not (clue_dots.issubset(set(path)) and set(adj.keys()).issubset(set(path))):
                                    return None, None
                            break
            if not added: break
        return true_edges, false_edges

    def get_final_loop(true_edges):
        if not true_edges: return None
        adj = collections.defaultdict(list)
        for p1, p2 in true_edges:
            adj[p1].append(p2)
            adj[p2].append(p1)
        if any(len(v) != 2 for v in adj.values()): return None

        start = next(iter(adj))
        path = [start]
        curr, prev = adj[start][0], start
        while curr != start:
            path.append(curr)
            next_node = adj[curr][0] if adj[curr][0] != prev else adj[curr][1]
            prev, curr = curr, next_node
        path.append(start)
        return path if clue_dots.issubset(set(path)) else None

    def backtrack(idx, true_edges, false_edges):
        true_edges, false_edges = propagate(true_edges.copy(), false_edges.copy())
        if true_edges is None: return None

        if idx == len(sorted_clues):
            # All clues satisfied, now connect remaining degree-1 dots
            return solve_remaining(true_edges, false_edges)

        pos, t, k = sorted_clues[idx]
        for cfg in clue_configs[pos]:
            if any(e in false_edges for e in cfg['true']) or any(e in true_edges for e in cfg['false']):
                continue
            res = backtrack(idx + 1, true_edges | cfg['true'], false_edges | cfg['false'])
            if res: return res
        return None

    def solve_remaining(true_edges, false_edges):
        true_edges, false_edges = propagate(true_edges, false_edges)
        if true_edges is None: return None

        loop = get_final_loop(true_edges)
        if loop: return loop

        # Pick a degree-1 dot and extend it
        degrees = collections.defaultdict(int)
        for p1, p2 in true_edges:
            degrees[p1] += 1; degrees[p2] += 1

        for p in list(degrees.keys()):
            if degrees[p] == 1:
                for n in get_neighbors(p):
                    e = get_edge(p, n)
                    if e not in true_edges and e not in false_edges:
                        res = solve_remaining(true_edges | {e}, false_edges)
                        if res: return res
                return None
        return None

    return backtrack(0, set(), set())

