def solve(observation):
    """
    Solves the Skyscrapers puzzle using logical deduction and backtracking with pruning.
    """
    N = len(observation['U'])

    def get_visible(line):
        count = 0
        max_h = 0
        for h in line:
            if h > max_h:
                count += 1
                max_h = h
        return count

    def is_valid_line(line, clue):
        if 0 in line: return True # Incomplete line
        if clue == 0: return True
        return get_visible(line) == clue

    def is_consistent(grid, r, c, val):
        # Check row uniqueness
        for j in range(N):
            if grid[r][j] == val: return False
        # Check col uniqueness
        for i in range(N):
            if grid[i][c] == val: return False

        # Check row clues if row is complete
        row = grid[r][:]
        row[c] = val
        if 0 not in row:
            if observation['L'][r] != 0 and not is_valid_line(row, observation['L'][r]): return False
            if observation['R'][r] != 0 and not is_valid_line(row[::-1], observation['R'][r]): return False
        else:
            # Partial row visibility check (pruning)
            if observation['L'][r] != 0:
                visible = 0
                max_h = 0
                for x in row:
                    if x == 0: break
                    if x > max_h:
                        visible += 1
                        max_h = x
                if visible > observation['L'][r]: return False
            if observation['R'][r] != 0:
                visible = 0
                max_h = 0
                for x in row[::-1]:
                    if x == 0: break
                    if x > max_h:
                        visible += 1
                        max_h = x
                if visible > observation['R'][r]: return False

        # Check col clues if col is complete
        col = [grid[i][c] for i in range(N)]
        col[r] = val
        if 0 not in col:
            if observation['U'][c] != 0 and not is_valid_line(col, observation['U'][c]): return False
            if observation['D'][c] != 0 and not is_valid_line(col[::-1], observation['D'][c]): return False
        else:
            # Partial col visibility check (pruning)
            if observation['U'][c] != 0:
                visible = 0
                max_h = 0
                for x in col:
                    if x == 0: break
                    if x > max_h:
                        visible += 1
                        max_h = x
                if visible > observation['U'][c]: return False
            if observation['D'][c] != 0:
                visible = 0
                max_h = 0
                for x in col[::-1]:
                    if x == 0: break
                    if x > max_h:
                        visible += 1
                        max_h = x
                if visible > observation['D'][c]: return False

        return True

    def backtrack(grid, r, c):
        if r == N:
            return grid

        next_r, next_c = (r, c + 1) if c < N - 1 else (r + 1, 0)

        # Try values from N down to 1 for potentially faster pruning
        for val in range(N, 0, -1):
            if is_consistent(grid, r, c, val):
                grid[r][c] = val
                res = backtrack(grid, next_r, next_c)
                if res: return res
                grid[r][c] = 0
        return None

    initial_grid = [[0 for _ in range(N)] for _ in range(N)]
    solution = backtrack(initial_grid, 0, 0)
    return solution if solution else "No Solution"

