            return current_grid

        for row_perm in row_candidates[row_idx]:
            is_consistent = True
            for col_idx in range(N):
                val = row_perm[col_idx]

                # 1. Latin Square Constraint: Column uniqueness
                for prev_row in range(row_idx):
                    if current_grid[prev_row][col_idx] == val:
                        is_consistent = False
                        break
                if not is_consistent:
                    break

                # 2. Visibility Constraint: Top-down partial check
