                    if not is_valid(col_prefix[::-1], bottom_clue):
                        is_consistent = False
                        break

            if is_consistent:
                result = backtrack(row_idx + 1, current_grid + [list(row_perm)])
                if result:
                    return result
        return None

    solution = backtrack(0, [])
    return solution if solution else "No Solution"

