def reduce_candidates(row_cands, col_cands, n):
    """Aggressively prunes candidate permutations using cross-consistency between rows and columns."""
    changed = True
    while changed:
        changed = False
        for r in range(n):
            for c in range(n):
                # Values possible at cell (r, c) from the perspective of row r
                vals_from_rows = {p[c] for p in row_cands[r]}
                # Values possible at cell (r, c) from the perspective of column c
                # Note: col_cands[c] contains permutations of column c (top to bottom)
                vals_from_cols = {p[r] for p in col_cands[c]}

                common = vals_from_rows & vals_from_cols
                if not common:
                    return False  # Inconsistent state

                if len(common) < len(vals_from_rows):
                    row_cands[r] = [p for p in row_cands[r] if p[c] in common]
                    changed = True
                if len(common) < len(vals_from_cols):
                    col_cands[c] = [p for p in col_cands[c] if p[r] in common]
                    changed = True
