            for c in range(n):
                col = tuple(grid[i][c] for i in range(n))
                if col not in col_sets[c]:
                    return False
            return True

        # Track values already used in each column to maintain uniqueness
        used_in_cols = [set(grid[i][c] for i in range(r)) for c in range(n)]

        # Sort candidates to prioritize rows with fewer options (heuristic)
        # For simplicity in this generalized solver, we iterate through row_candidates[r]
