class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []

    def find(self, i):
        while self.parent[i] != i:
            i = self.parent[i]
        return i

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            if self.size[root_i] < self.size[root_j]:
                root_i, root_j = root_j, root_i
            self.history.append((root_j, root_i, self.size[root_i]))
            self.parent[root_j] = root_i
            self.size[root_i] += self.size[root_j]
            return True
        else:
            self.history.append(None)
            return False

    def undo(self):
        last = self.history.pop()
        if last:
            child, parent, old_size = last
            self.parent[child] = child
            self.size[parent] = old_size

def solve(observation):
    clues = observation['data']
    N = len(clues) - 1
    grid = [[None] * N for _ in range(N)]
    dot_fixed = [[0] * (N + 1) for _ in range(N + 1)]
