        for dc in range(N + 1):
            count = 0
            if dr > 0 and dc > 0: count += 1
            if dr > 0 and dc < N: count += 1
            if dr < N and dc > 0: count += 1
            if dr < N and dc < N: count += 1
            dot_undecided[dr][dc] = count

