    for r in range(N):
        row_dots = []
        for c in range(N):
            row_dots.append({
                'all': [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)],
                '\\': [(r, c), (r + 1, c + 1)],
                '/': [(r + 1, c), (r, c + 1)]
            })
        cell_dots.append(row_dots)

    dsu = DSU((N + 1) * (N + 1))

    def can_place(r, c, diag):
        dots = cell_dots[r][c]
        connected = dots[diag]
        for dr, dc in dots['all']:
            clue = clues[dr][dc]
            if clue is None: continue

