            node, old_parent, rank_increased = self.history.pop()
            if rank_increased:
                self.rank[self.parent[node]] -= 1
            self.parent[node] = old_parent

def solve(observation):
    data = observation['data']
    N = len(data) - 1
    grid = [[None] * N for _ in range(N)]
    dot_counts = [[0] * (N + 1) for _ in range(N + 1)]
    dot_rem = [[0] * (N + 1) for _ in range(N + 1)]
    dsu = DSU((N + 1) * (N + 1))

    for r in range(N + 1):
        for c in range(N + 1):
            count = 0
            if r > 0 and c > 0: count += 1
            if r > 0 and c < N: count += 1
            if r < N and c > 0: count += 1
            if r < N and c < N: count += 1
            dot_rem[r][c] = count

    def is_valid(r, c, diag):
        # Cycle check
        if diag == '\\':
            d1, d2 = r * (N + 1) + c, (r + 1) * (N + 1) + (c + 1)
        else:
            d1, d2 = r * (N + 1) + (c + 1), (r + 1) * (N + 1) + c
        if dsu.find(d1) == dsu.find(d2):
            return False

