        for dr in [0, 1]:
            for dc in [0, 1]:
                nr, nc = r + dr, c + dc
                clue = data[nr][nc]
                if clue is None: continue

                is_conn = False
                if diag == '\\':
                    if (dr == 0 and dc == 0) or (dr == 1 and dc == 1): is_conn = True
                else:
                    if (dr == 0 and dc == 1) or (dr == 1 and dc == 0): is_conn = True

                cnt = dot_counts[nr][nc] + (1 if is_conn else 0)
                rem = dot_rem[nr][nc] # already decremented in backtrack
                if cnt > clue or cnt + rem < clue:
                    return False
        return True

    def backtrack(idx):
        if idx == N * N:
            return True
        r, c = divmod(idx, N)

        for dr in [0, 1]:
            for dc in [0, 1]:
                dot_rem[r + dr][c + dc] -= 1

        for diag in ['\\', '/']:
            if is_valid(r, c, diag):
                h_size = len(dsu.history)
                if diag == '\\':
                    d1, d2 = r * (N + 1) + c, (r + 1) * (N + 1) + (c + 1)
                    dot_counts[r][c] += 1
                    dot_counts[r + 1][c + 1] += 1
                else:
                    d1, d2 = r * (N + 1) + (c + 1), (r + 1) * (N + 1) + c
                    dot_counts[r][c + 1] += 1
                    dot_counts[r + 1][c] += 1

                dsu.union(d1, d2)
                grid[r][c] = diag
                if backtrack(idx + 1):
                    return True

                # Rollback
                dsu.rollback(h_size)
                if diag == '\\':
                    dot_counts[r][c] -= 1
                    dot_counts[r + 1][c + 1] -= 1
                else:
                    dot_counts[r][c + 1] -= 1
                    dot_counts[r + 1][c] -= 1
                grid[r][c] = None

        for dr in [0, 1]:
            for dc in [0, 1]:
                dot_rem[r + dr][c + dc] += 1
        return False

    if backtrack(0):
        return grid
    else:
        return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))
