import sys

# Slitherlink Solver
# Rules:
# 1. Form a single closed loop by connecting dots.
# 2. Numbers in cells indicate how many of its four edges are part of the loop.
# 3. The loop must not cross or branch.

OBSERVATION = {
    'data': [
        [None, None, None, 1, None],
        [2, None, 1, 1, None],
        [2, None, 2, None, None],
        [1, 2, 0, 2, None],
        [None, 3, 3, 3, None]
    ]
}

def solve(observation):
    grid = observation['data']
    R = len(grid)
    C = len(grid[0])

    # Edges: horizontal (r, c, r, c+1) and vertical (r, c, r+1, c)
    # Status: 0 = unknown, 1 = in loop, -1 = not in loop
    edges = {}
    for r in range(R + 1):
        for c in range(C):
            edges[((r, c), (r, c + 1))] = 0
    for r in range(R):
        for c in range(C + 1):
            edges[((r, c), (r + 1, c))] = 0

    def get_cell_edges(r, c):
        return [
            ((r, c), (r, c + 1)),         # top
            ((r + 1, c), (r + 1, c + 1)), # bottom
            ((r, c), (r + 1, c)),         # left
            ((r, c + 1), (r + 1, c + 1))  # right
        ]

    def get_dot_edges(r, c):
        res = []
        if r > 0: res.append(((r - 1, c), (r, c)))
        if r < R: res.append(((r, c), (r + 1, c)))
        if c > 0: res.append(((r, c - 1), (r, c)))
        if c < C: res.append(((r, c), (r, c + 1)))
        return res

    def propagate(state):
        changed = True
        while changed:
            changed = False
            # Cell constraints
            for r in range(R):
                for c in range(C):
                    clue = grid[r][c]
                    if clue is None: continue
                    cell_edges = get_cell_edges(r, c)
                    ins = [e for e in cell_edges if state[e] == 1]
                    outs = [e for e in cell_edges if state[e] == -1]
                    unknowns = [e for e in cell_edges if state[e] == 0]

                    if len(ins) > clue or len(ins) + len(unknowns) < clue:
                        return False
                    if len(ins) == clue:
                        for e in unknowns:
                            state[e] = -1
                            changed = True
                    elif len(ins) + len(unknowns) == clue:
                        for e in unknowns:
                            state[e] = 1
                            changed = True

            # Dot constraints (degree 0 or 2)
            for r in range(R + 1):
                for c in range(C + 1):
                    dot_edges = get_dot_edges(r, c)
                    ins = [e for e in dot_edges if state[e] == 1]
                    outs = [e for e in dot_edges if state[e] == -1]
                    unknowns = [e for e in dot_edges if state[e] == 0]

                    if len(ins) > 2: return False
                    if len(ins) == 1 and not unknowns: return False
                    if len(ins) == 2:
                        for e in unknowns:
                            state[e] = -1
                            changed = True
                    if len(ins) == 1 and len(unknowns) == 1:
                        state[unknowns[0]] = 1
                        changed = True
                    if len(outs) == len(dot_edges) - 1 and unknowns:
                        state[unknowns[0]] = -1
                        changed = True
        return True

    def get_loop(state):
        in_edges = [e for e, s in state.items() if s == 1]
        if not in_edges: return None

        adj = {}
        for (p1, p2) in in_edges:
            adj.setdefault(p1, []).append(p2)
            adj.setdefault(p2, []).append(p1)

        start_node = in_edges[0][0]
        loop = [start_node]
        curr = start_node
        prev = None

        while True:
            neighbors = adj.get(curr, [])
            if len(neighbors) != 2: return None
            next_node = neighbors[0] if neighbors[0] != prev else neighbors[1]
            if next_node == start_node:
                loop.append(start_node)
                return loop if len(loop) == len(in_edges) + 1 else None
            loop.append(next_node)
            prev, curr = curr, next_node

    def backtrack(state):
        if not propagate(state): return None

        # Check if solved
        loop = get_loop(state)
        if loop:
            # Verify all clues
            for r in range(R):
                for c in range(C):
                    if grid[r][c] is not None:
                        if sum(1 for e in get_cell_edges(r, c) if state[e] == 1) != grid[r][c]:
                            return None
            return loop

        # Heuristic: pick edge near clues or existing loop
        best_edge = None
        for r in range(R):
            for c in range(C):
                if grid[r][c] is not None:
                    for e in get_cell_edges(r, c):
                        if state[e] == 0:
                            best_edge = e
                            break
                if best_edge: break
            if best_edge: break

        if not best_edge:
            for e, s in state.items():
                if s == 0:
                    best_edge = e
                    break

        if not best_edge: return None

        for val in [1, -1]:
            new_state = state.copy()
            new_state[best_edge] = val
            res = backtrack(new_state)
            if res: return res
        return None

    return backtrack(edges)

if __name__ == "__main__":
    print(solve(OBSERVATION))

