    # v_edges[r][c] is between (r, c) and (r+1, c)
    # State: 0 = unknown, 1 = in loop, -1 = not in loop
    h_edges = [[0 for _ in range(C)] for _ in range(R + 1)]
    v_edges = [[0 for _ in range(C + 1)] for _ in range(R)]

    def get_cell_edges(r, c):
        return [
            ('h', r, c), ('h', r + 1, c),
            ('v', r, c), ('v', r, c + 1)
        ]

    def get_dot_edges(r, c):
        edges = []
        if r > 0: edges.append(('v', r - 1, c))
        if r < R: edges.append(('v', r, c))
        if c > 0: edges.append(('h', r, c - 1))
        if c < C: edges.append(('h', r, c))
        return edges

    def get_val(edge):
        t, r, c = edge
        return h_edges[r][c] if t == 'h' else v_edges[r][c]

    def set_val(edge, val):
        t, r, c = edge
        if t == 'h': h_edges[r][c] = val
        else: v_edges[r][c] = val

    def propagate():
        changed = True
        while changed:
            changed = False
            # Clue constraints
            for r in range(R):
                for c in range(C):
                    clue = clues[r][c]
                    if clue is None: continue
                    edges = get_cell_edges(r, c)
                    vals = [get_val(e) for e in edges]
                    in_count = vals.count(1)
                    out_count = vals.count(-1)
                    unknown = [e for e in edges if get_val(e) == 0]

                    if in_count > clue or in_count + len(unknown) < clue:
                        return False
                    if in_count == clue and unknown:
                        for e in unknown: set_val(e, -1)
                        changed = True
                    elif in_count + len(unknown) == clue and unknown:
                        for e in unknown: set_val(e, 1)
                        changed = True

            # Dot degree constraints (0 or 2)
            for r in range(R + 1):
                for c in range(C + 1):
                    edges = get_dot_edges(r, c)
                    vals = [get_val(e) for e in edges]
                    in_count = vals.count(1)
                    out_count = vals.count(-1)
                    unknown = [e for e in edges if get_val(e) == 0]

                    if in_count > 2: return False
                    if in_count == 1 and not unknown: return False
                    if in_count == 2 and unknown:
                        for e in unknown: set_val(e, -1)
                        changed = True
                    if in_count == 1 and len(unknown) == 1:
                        set_val(unknown[0], 1)
                        changed = True
                    if in_count == 0 and len(unknown) == 1:
                        set_val(unknown[0], -1)
                        changed = True

            # Connectivity: No small loops
            # If a loop is closed, it must satisfy all clues and contain all IN edges.
            # This is handled by the backtracking and final check.
        return True

    def get_loop():
        # Find any dot with degree 2
        start_dot = None
        for r in range(R + 1):
            for c in range(C + 1):
                if [get_val(e) for e in get_dot_edges(r, c)].count(1) == 2:
                    start_dot = (r, c)
                    break
            if start_dot: break

        if not start_dot: return None

        loop = [start_dot]
        curr = start_dot
        prev = None
        while True:
            next_dot = None
            for e in get_dot_edges(curr[0], curr[1]):
                if get_val(e) == 1:
                    t, r, c = e
                    if t == 'h': d = (r, c) if (r, c) != curr else (r, c + 1)
                    else: d = (r, c) if (r, c) != curr else (r + 1, c)
                    if d != prev:
                        next_dot = d
                        break
            if next_dot == start_dot:
                loop.append(start_dot)
                return loop
            if not next_dot: return None # Should not happen if degree is 2
            loop.append(next_dot)
            prev, curr = curr, next_dot

    def is_complete():
        for r in range(R + 1):
            for c in range(C):
                if h_edges[r][c] == 0: return False
        for r in range(R):
            for c in range(C + 1):
                if v_edges[r][c] == 0: return False
        return True

    def check_final():
        loop = get_loop()
        if not loop: return False
        # Check if all IN edges are in the loop
        in_edges_count = 0
        for r in range(R + 1): in_edges_count += h_edges[r].count(1)
        for r in range(R): in_edges_count += v_edges[r].count(1)
        if in_edges_count != len(loop) - 1: return False
        # Check clues
        for r in range(R):
            for c in range(C):
                if clues[r][c] is not None:
                    if [get_val(e) for e in get_cell_edges(r, c)].count(1) != clues[r][c]:
                        return False
        return True

    def backtrack():
        if not propagate(): return None

        # Find an unknown edge
        target = None
        for r in range(R + 1):
            for c in range(C):
                if h_edges[r][c] == 0:
                    target = ('h', r, c)
                    break
            if target: break
        if not target:
            for r in range(R):
                for c in range(C + 1):
                    if v_edges[r][c] == 0:
                        target = ('v', r, c)
                        break
                if target: break

        if not target:
            return get_loop() if check_final() else None

        # Try IN
        state_h = [row[:] for row in h_edges]
        state_v = [row[:] for row in v_edges]
        set_val(target, 1)
        res = backtrack()
        if res: return res

        # Try OUT
        for r in range(R + 1): h_edges[r] = state_h[r][:]
        for r in range(R): v_edges[r] = state_v[r][:]
        set_val(target, -1)
        return backtrack()

    result = backtrack()
    return result if result else "No Solution"

