import collections

class SlitherlinkSolver:
    def __init__(self, observation):
        self.data = observation['data']
        self.R = len(self.data)
        self.C = len(self.data[0])
        self.num_horiz = (self.R + 1) * self.C
        self.num_vert = self.R * (self.C + 1)
        self.total_edges = self.num_horiz + self.num_vert
        self.num_dots = (self.R + 1) * (self.C + 1)
        self.num_cells = self.R * self.C

        self.edge_state = [-1] * self.total_edges  # -1: UNKNOWN, 0: OUT, 1: IN
        self.cell_in_counts = [0] * self.num_cells
        self.cell_out_counts = [0] * self.num_cells
        self.dot_degrees = [0] * self.num_dots
        self.dot_out_counts = [0] * self.num_dots
        self.undo_stack = []

        self.cell_clues = []
        for r in range(self.R):
            for c in range(self.C):
                if self.data[r][c] is not None:
                    self.cell_clues.append((r * self.C + c, self.data[r][c]))

        self.cell_edges = [[] for _ in range(self.num_cells)]
        for r in range(self.R):
            for c in range(self.C):
                idx = r * self.C + c
                self.cell_edges[idx] = [
                    r * self.C + c,  # top
                    (r + 1) * self.C + c,  # bottom
                    self.num_horiz + r * (self.C + 1) + c,  # left
                    self.num_horiz + r * (self.C + 1) + c + 1  # right
                ]

        self.dot_edges = [[] for _ in range(self.num_dots)]
        for r in range(self.R + 1):
            for c in range(self.C + 1):
                idx = r * (self.C + 1) + c
                if c < self.C: self.dot_edges[idx].append(r * self.C + c)  # right
                if c > 0: self.dot_edges[idx].append(r * self.C + c - 1)  # left
                if r < self.R: self.dot_edges[idx].append(self.num_horiz + r * (self.C + 1) + c)  # down
                if r > 0: self.dot_edges[idx].append(self.num_horiz + (r - 1) * (self.C + 1) + c)  # up

        self.edge_cells = [[] for _ in range(self.total_edges)]
        for c_idx, edges in enumerate(self.cell_edges):
            for e_idx in edges:
                self.edge_cells[e_idx].append(c_idx)

        self.edge_dots = [[] for _ in range(self.total_edges)]
        for d_idx, edges in enumerate(self.dot_edges):
            for e_idx in edges:
                self.edge_dots[e_idx].append(d_idx)

    def set_edge(self, edge_id, state):
        if self.edge_state[edge_id] != -1:
            return self.edge_state[edge_id] == state
        self.undo_stack.append((edge_id, -1))
        self.edge_state[edge_id] = state
        for c_idx in self.edge_cells[edge_id]:
            if state == 1: self.cell_in_counts[c_idx] += 1
            else: self.cell_out_counts[c_idx] += 1
        for d_idx in self.edge_dots[edge_id]:
            if state == 1: self.dot_degrees[d_idx] += 1
            else: self.dot_out_counts[d_idx] += 1
        return True

    def undo(self, target_len):
        while len(self.undo_stack) > target_len:
            edge_id, _ = self.undo_stack.pop()
            state = self.edge_state[edge_id]
            self.edge_state[edge_id] = -1
