def solve(observation):
    """
    Solves the Star Battle puzzle using backtracking with human-like pruning and heuristics.
    """
    grid = observation['data']
    n = len(grid)

    # Group cells by region
    regions_map = {}
    for r in range(n):
        for c in range(n):
            reg_id = grid[r][c]
            if reg_id not in regions_map:
                regions_map[reg_id] = []
            regions_map[reg_id].append((r, c))

    # Convert to a list of regions and sort by size (heuristic: process smaller regions first)
    region_list = list(regions_map.values())
    region_list.sort(key=len)
    n_regions = len(region_list)

    def is_safe(r, c, stars):
        """
        Checks if placing a star at (r, c) violates the adjacency rule (8 directions).
        Row and column constraints are handled by the backtracking state.
        """
        for sr, sc in stars:
            if abs(r - sr) <= 1 and abs(c - sc) <= 1:
                return False
        return True

    def backtrack(reg_idx, stars, used_rows, used_cols):
        """
        Recursive backtracking with constraint propagation and pruning.
        """
        # Base case: all regions have a star
        if reg_idx == n_regions:
            return stars

        # Pruning: Check if every remaining region still has at least one valid cell
        for i in range(reg_idx, n_regions):
            has_valid = False
            for r, c in region_list[i]:
                if r not in used_rows and c not in used_cols and is_safe(r, c, stars):
                    has_valid = True
                    break
            if not has_valid:
                return None

        # Try placing a star in each valid cell of the current region
        current_region = region_list[reg_idx]
        for r, c in current_region:
            if r not in used_rows and c not in used_cols and is_safe(r, c, stars):
                # Place star
                res = backtrack(reg_idx + 1, stars + [(r, c)], used_rows | {r}, used_cols | {c})
                if res:
                    return res

        return None

    # Execute the solver
    solution_stars = backtrack(0, [], set(), set())

    if solution_stars:
        # Construct the output grid
        result_grid = [[None for _ in range(n)] for _ in range(n)]
        for r, c in solution_stars:
            result_grid[r][c] = 'S'
        return result_grid
    else:
        return "No Solution"

