        [0, 5, 6, 6, 6, 7, 7, 7],
        [5, 5, 6, 6, 6, 7, 7, 7],
        [6, 6, 6, 6, 6, 7, 7, 7]
    ]
}

def solve(observation):
    grid_data = observation['data']
    n = len(grid_data)

    # Group cells by region
    regions = {}
    for r in range(n):
        for c in range(n):
            reg_id = grid_data[r][c]
            if reg_id not in regions:
                regions[reg_id] = []
            regions[reg_id].append((r, c))

    region_ids = sorted(regions.keys())
    num_regions = len(region_ids)

    # Precompute neighbors for each cell
    neighbors = {}
    for r in range(n):
        for c in range(n):
            nb = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        nb.append((nr, nc))
            neighbors[(r, c)] = nb

    def is_valid(r, c, stars):
        # Check row and column
        for sr, sc in stars:
            if sr == r or sc == c:
                return False
            # Check diagonal/adjacent touching
            if abs(sr - r) <= 1 and abs(sc - c) <= 1:
                return False
        return True

    def get_possible_cells(reg_id, stars, forbidden):
        possible = []
        for r, c in regions[reg_id]:
            if (r, c) not in forbidden:
                # Check row/col/neighbors against current stars
                if is_valid(r, c, stars):
                    possible.append((r, c))
        return possible

    def backtrack(reg_idx, stars, forbidden):
        if reg_idx == num_regions:
            return stars

        # Heuristic: Pick region with fewest remaining possibilities (MRV)
        best_reg_id = -1
        min_possibilities = float('inf')
        remaining_regions = [rid for rid in region_ids if rid not in [grid_data[r][c] for r, c in stars]]

        for rid in remaining_regions:
            poss = get_possible_cells(rid, stars, forbidden)
            if len(poss) == 0:
                return None
            if len(poss) < min_possibilities:
                min_possibilities = len(poss)
                best_reg_id = rid

        if best_reg_id == -1:
            return None

        possibilities = get_possible_cells(best_reg_id, stars, forbidden)
        for r, c in possibilities:
            # Place star
            new_stars = stars + [(r, c)]
            # Update forbidden cells for efficiency
            new_forbidden = forbidden.copy()
            # All cells in same region are forbidden
            for cell in regions[best_reg_id]:
                new_forbidden.add(cell)
            # All cells in same row/col are forbidden (though is_valid checks this too)
            # Neighbors are forbidden
            for nb in neighbors[(r, c)]:
                new_forbidden.add(nb)

            result = backtrack(reg_idx + 1, new_stars, new_forbidden)
            if result:
                return result

        return None

    # Start solving
    solution_stars = backtrack(0, [], set())

    if solution_stars:
        # Create output grid
        res_grid = [[None for _ in range(n)] for _ in range(n)]
        for r, c in solution_stars:
            res_grid[r][c] = 'S'
        return res_grid
    else:
        return "No Solution"

