        [6, 6, 6, 6, 6, 6, 8, 8, 8, 3]
    ]
}

def solve(observation):
    N = 10
    grid = observation['data']
    region_cells = collections.defaultdict(set)
    for r in range(N):
        for c in range(N):
            region_cells[grid[r][c]].add((r, c))

    units = []
    # Rows
    for r in range(N): units.append(set((r, c) for c in range(N)))
    # Columns
    for c in range(N): units.append(set((r, c) for r in range(N)))
    # Regions
    for rid in region_cells: units.append(region_cells[rid])

    # Precompute adjacency
    adj = collections.defaultdict(set)
    for r in range(N):
        for c in range(N):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0: continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        adj[(r, c)].add((nr, nc))

    def propagate(stars, forbidden):
        stars = set(stars)
        forbidden = set(forbidden)
        while True:
            start_count = len(stars) + len(forbidden)

            # Rule 1: Star neighbors are forbidden
            for s in stars:
                forbidden.update(adj[s])

            for u in units:
                u_stars = u & stars
                u_forbidden = u & forbidden
                u_available = u - stars - forbidden

                # Consistency check
                if len(u_stars) > 2 or len(u_stars) + len(u_available) < 2:
                    return None, None

                # Rule 2: If unit has 2 stars, rest are forbidden
                if len(u_stars) == 2:
                    forbidden.update(u_available)
                # Rule 3: If unit must have remaining available cells as stars
                elif len(u_stars) + len(u_available) == 2:
                    stars.update(u_available)

            if len(stars) + len(forbidden) == start_count:
                break
        return stars, forbidden

    def search(stars, forbidden):
        stars, forbidden = propagate(stars, forbidden)
        if stars is None: return None

        # Check if all units are satisfied
        if all(len(u & stars) == 2 for u in units):
            return stars

        # Heuristic: pick unit with fewest available cells
        best_u = None
        min_avail = float('inf')
        for u in units:
            u_stars_count = len(u & stars)
            if u_stars_count < 2:
                u_available = u - stars - forbidden
                if len(u_available) < min_avail:
                    min_avail = len(u_available)
                    best_u = u

        if best_u is None: return None

        # Branching
        u_available = sorted(list(best_u - stars - forbidden))
        for c in u_available:
            if c in forbidden: continue
            res = search(stars | {c}, forbidden)
            if res: return res
            # Pruning: if placing a star at 'c' failed, 'c' must be forbidden
            forbidden = forbidden | {c}
            stars, forbidden = propagate(stars, forbidden)
            if stars is None: break

        return None

    result_stars = search(set(), set())
    if result_stars:
        res_grid = [[None for _ in range(N)] for _ in range(N)]
        for r, c in result_stars:
            res_grid[r][c] = 'S'
        return res_grid
    return "No Solution"

