def solve(observation):
    grid = observation['data']
    N = len(grid)

    # status: 0=unknown, 1=star, 2=eliminated
    def get_initial_status():
        status = [[0 for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'B':
                    status[r][c] = 2
        return status

    def propagate(status):
        changed = True
        while changed:
            changed = False
            # 1. Star placement consequences: eliminate row, col, and 8 neighbors
            for r in range(N):
                for c in range(N):
                    if status[r][c] == 1:
                        # Eliminate row
                        for j in range(N):
                            if j != c:
                                if status[r][j] == 1: return False # Contradiction: two stars in row
                                if status[r][j] == 0: status[r][j] = 2; changed = True
                        # Eliminate col
                        for i in range(N):
                            if i != r:
                                if status[i][c] == 1: return False # Contradiction: two stars in col
                                if status[i][c] == 0: status[i][c] = 2; changed = True
                        # Eliminate 8 neighbors
                        for dr in [-1, 0, 1]:
                            for dc in [-1, 0, 1]:
                                if dr == 0 and dc == 0: continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < N and 0 <= nc < N:
                                    if status[nr][nc] == 1: return False # Contradiction: touching stars
                                    if status[nr][nc] == 0: status[nr][nc] = 2; changed = True

            # 2. Forced stars: if a row/col has only one possible spot, place a star
            for r in range(N):
                if 1 not in status[r]:
                    zeros = [c for c in range(N) if status[r][c] == 0]
                    if not zeros: return False # Contradiction: no spot for star in row
                    if len(zeros) == 1: status[r][zeros[0]] = 1; changed = True
            for c in range(N):
                has_star = any(status[r][c] == 1 for r in range(N))
                if not has_star:
                    zeros = [r for r in range(N) if status[r][c] == 0]
                    if not zeros: return False # Contradiction: no spot for star in col
                    if len(zeros) == 1: status[zeros[0]][c] = 1; changed = True
        return True

    def backtrack(status):
        # Work on a copy to avoid side effects
        status = [row[:] for row in status]
        if not propagate(status):
            return None

        # Check if solved
        star_count = sum(row.count(1) for row in status)
        if star_count == N:
            return status

        # Heuristic: pick row with fewest remaining possible spots (0s)
        best_row = -1
        min_zeros = float('inf')
        for r in range(N):
            if 1 not in status[r]:
                zeros = [c for c in range(N) if status[r][c] == 0]
                if len(zeros) < min_zeros:
                    min_zeros = len(zeros)
                    best_row = r

        if best_row == -1:
            return None # Should not happen if star_count < N

        zeros = [c for c in range(N) if status[best_row][c] == 0]
        for c in zeros:
            new_status = [row[:] for row in status]
            new_status[best_row][c] = 1
            result = backtrack(new_status)
            if result:
                return result

        return None

    initial_status = get_initial_status()
    final_status = backtrack(initial_status)

    if final_status:
        result_grid = [[None for _ in range(N)] for _ in range(N)]
        for r in range(N):
            for c in range(N):
                if final_status[r][c] == 1:
                    result_grid[r][c] = 'S'
        return result_grid
    else:
        return "No Solution"

