            new_row_counts[h2[0]] += 1
            new_col_counts[h1[1]] += 1
            new_col_counts[h2[1]] += 1

            res = backtrack(idx + 1, current_stitches + [[h1, h2]], used_holes | {h1, h2}, new_row_counts, new_col_counts)
            if res: return res

        # Option 2: Skip this stitch
