    Implements human-like deduction rules (Naked Singles, Hidden Singles) and MRV heuristic.
    """
    data = observation['data']
    unit_str = observation['unit']

    # Determine subgrid dimensions R (rows) and C (cols)
    if 'x' in unit_str:
        R, C = map(int, unit_str.split('x'))
    else:
        R = C = int(unit_str)

    N = R * C
    digits = range(1, N + 1)
    cells = [(r, c) for r in range(N) for c in range(N)]

    # Precompute units and peers for each cell to speed up constraint propagation
    def get_units():
        u = []
        # Rows
        for r in range(N): u.append([(r, c) for c in range(N)])
        # Columns
        for c in range(N): u.append([(r, c) for r in range(N)])
        # Subgrids (Boxes)
        for br in range(0, N, R):
            for bc in range(0, N, C):
                u.append([(r, c) for r in range(br, br + R) for c in range(bc, bc + C)])
        return u

    all_units = get_units()
    units_of_cell = {cell: [u for u in all_units if cell in u] for cell in cells}
    peers = {cell: set(sum(units_of_cell[cell], [])) - {cell} for cell in cells}

    def assign(values, cell, val):
        """
        Eliminate all other values from values[cell] and propagate constraints.
        Returns the updated values dictionary, or None if a contradiction is found.
        """
        other_values = values[cell] - {val}
        if all(eliminate(values, cell, v) for v in other_values):
            return values
        return None

    def eliminate(values, cell, val):
        """
        Eliminate val from values[cell] and apply deductive rules.
        Rule 1: Naked Singles - If a cell is reduced to one value, eliminate it from peers.
        Rule 2: Hidden Singles - If a unit has only one possible place for a value, assign it.
        """
        if val not in values[cell]:
            return values # Already eliminated

        values[cell].remove(val)

        # Rule 1: Naked Singles
        if len(values[cell]) == 0:
            return None # Contradiction: no possible values left
        elif len(values[cell]) == 1:
            v2 = next(iter(values[cell]))
            if not all(eliminate(values, p, v2) for p in peers[cell]):
                return None

        # Rule 2: Hidden Singles
        for u in units_of_cell[cell]:
            dplaces = [c for c in u if val in values[c]]
            if len(dplaces) == 0:
                return None # Contradiction: value cannot be placed in this unit
            elif len(dplaces) == 1:
                if not assign(values, dplaces[0], val):
