        Backtracking search with constraint propagation.
        Uses Minimum Remaining Values (MRV) heuristic to select the next cell to branch on.
        """
        if values is None:
            return None
        if all(len(values[cell]) == 1 for cell in cells):
            return values # Puzzle solved

        # MRV heuristic: choose the unfilled cell with the fewest remaining possibilities
        unfilled = [cell for cell in cells if len(values[cell]) > 1]
        _, cell = min((len(values[cell]), cell) for cell in unfilled)

        # Try values in sorted order to maintain determinism
        for val in sorted(list(values[cell])):
            # Create a deep copy of the values dictionary for branching
            new_values = {k: v.copy() for k, v in values.items()}
            res = search(assign(new_values, cell, val))
            if res:
                return res
        return None

    # Execute the solver
    initial_values = parse_grid(data)
    result_values = search(initial_values)

    if result_values:
        # Convert the internal dictionary representation back to a 2D list
        res_grid = [[0]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                res_grid[r][c] = next(iter(result_values[(r, c)]))
        return res_grid
    else:
        return "No Solution"

