        if len(values[s]) == 0:
            return False # Contradiction
        elif len(values[s]) == 1:
            d2 = values[s][0]
            if not all(eliminate(values, s2, d2) for s2 in peers[s]):
                return False

        # Rule 2: If a unit is reduced to only one place for a value d, assign it there
        for u in units[s]:
            dplaces = [sq for sq in u if d in values[sq]]
            if len(dplaces) == 0:
                return False # Contradiction
            elif len(dplaces) == 1:
                if not assign(values, dplaces[0], d):
