        _, s = min((len(values[s]), s) for s in squares if len(values[s]) > 1)

        # Try each possible value for square s, branching the search
        for d in values[s]:
            # Create a deep copy of the current state for backtracking
            new_values = {k: list(v) for k, v in values.items()}
            res = search(assign(new_values, s, d))
            if res:
                return res
        return False

    # Execute the search starting from the initial constrained state
    result = search(values)

    if result:
        # Format the result back into a 2D grid of integers
        res_grid = [[0 for _ in range(n)] for _ in range(n)]
        for (r, c), val_list in result.items():
            res_grid[r][c] = val_list[0]
        return res_grid
    else:
        return "No Solution"

