            # Create local copies for this branch
            new_grid = [row[:] for row in grid]
            new_poss = [[set(p) for p in row] for row in poss]

            new_grid[r][c] = val
            new_poss[r][c] = set()
            update_poss(new_poss, r, c, val)

            if propagate(new_grid, new_poss):
                res = backtrack(new_grid, new_poss)
                if res:
                    return res
        return None

    # Initial setup and solving
    grid = [row[:] for row in data]
    poss = get_possibilities(grid)

    if not propagate(grid, poss):
        return "No Solution"

    result = backtrack(grid, poss)
    return result if result else "No Solution"

