    'col_tent_counts': [1, 2, 1, 2, 0, 2, 0, 4]
}

def solve(observation):
    tree_grid = observation['tree']
    R = len(tree_grid)
    C = len(tree_grid[0])
    row_targets = observation['row_tent_counts']
    col_targets = observation['col_tent_counts']

    trees = []
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                trees.append((r, c))

    num_trees = len(trees)

    # Precompute possible tent locations for each tree
    tree_to_options = {}
    for tr, tc in trees:
        options = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = tr + dr, tc + dc
            if 0 <= nr < R and 0 <= nc < C and tree_grid[nr][nc] is None:
                # Basic check: row/col not already full (target > 0)
                if row_targets[nr] > 0 and col_targets[nc] > 0:
                    options.append((nr, nc))
        tree_to_options[(tr, tc)] = options

    # Sort trees by number of options to improve backtracking efficiency (MRV heuristic)
    trees.sort(key=lambda t: len(tree_to_options[t]))

    # Backtracking state
    tent_grid = [[False for _ in range(C)] for _ in range(R)]
    row_counts = [0] * R
    col_counts = [0] * C

    def is_safe(r, c):
        # Check row and column capacity
        if row_counts[r] >= row_targets[r] or col_counts[c] >= col_targets[c]:
            return False
        # Check 8-neighbors for other tents (tents cannot touch)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0: continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C:
                    if tent_grid[nr][nc]:
                        return False
        return True

    def backtrack(tree_idx):
        # Base case: all trees have been paired with a tent
        if tree_idx == num_trees:
            # Final verification of row and column counts
            return row_counts == row_targets and col_counts == col_targets

        # Pruning: check if any remaining tree has no valid options left
        for i in range(tree_idx, num_trees):
            tr, tc = trees[i]
            can_place = False
            for nr, nc in tree_to_options[(tr, tc)]:
                if not tent_grid[nr][nc] and is_safe(nr, nc):
                    can_place = True
                    break
            if not can_place:
                return False

        # Try placing a tent for the current tree
        tr, tc = trees[tree_idx]
        for nr, nc in tree_to_options[(tr, tc)]:
            if not tent_grid[nr][nc] and is_safe(nr, nc):
                # Place tent
                tent_grid[nr][nc] = True
                row_counts[nr] += 1
                col_counts[nc] += 1

                # Recurse to the next tree
                if backtrack(tree_idx + 1):
                    return True

                # Backtrack: remove tent
                tent_grid[nr][nc] = False
                row_counts[nr] -= 1
                col_counts[nc] -= 1

        return False

    # Execute backtracking search
    if backtrack(0):
        # Construct the final grid result
        result_grid = [[None for _ in range(C)] for _ in range(R)]
        for r in range(R):
            for c in range(C):
                if tent_grid[r][c]:
                    result_grid[r][c] = 't'
        return result_grid
    else:
        return "No Solution"

