        [None, None, 'B', 'B', None, None, None, None, 'W', None],
        [None, 'B', None, None, 'B', None, None, None, None, None],
        [None, None, 'B', None, None, None, None, None, None, None],
        [None, None, None, None, 'W', 'B', 'B', None, None, None],
        [None, None, 'W', None, None, None, None, None, None, None],
        [None, None, None, None, None, 'W', None, 'W', 'W', None],
        [None, None, None, 'W', None, None, None, None, None, None],
        [None, None, None, None, None, None, None, None, None, None]
    ]
}

def solve(observation):
    grid_data = observation['data']
    R = len(grid_data)
    C = len(grid_data[0])
    grid = [row[:] for row in grid_data]

    def get_neighbors(r, c):
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    def can_connect(grid, color):
        """Checks if all cells of 'color' can still form a single connected component."""
        cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == color]
        if not cells:
            return True
        start = cells[0]
        q = collections.deque([start])
        visited = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in get_neighbors(r, c):
                if (grid[nr][nc] == color or grid[nr][nc] is None) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return all(cell in visited for cell in cells)

    def is_connected(grid, color):
        """Checks if all cells of 'color' are currently orthogonally connected."""
        cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == color]
        if not cells:
            return True
        start = cells[0]
        q = collections.deque([start])
        visited = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == color and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return len(visited) == len(cells)

    def check_2x2(grid, r, c):
        """Checks if the 2x2 block starting at (r, c) is all the same color."""
        if r < 0 or r >= R - 1 or c < 0 or c >= C - 1:
            return True
        vals = [grid[r][c], grid[r+1][c], grid[r][c+1], grid[r+1][c+1]]
        if None not in vals:
            if vals[0] == vals[1] == vals[2] == vals[3]:
                return False
        return True

    def get_boundary_changes(grid):
        """Calculates the minimum number of color changes around the grid perimeter."""
        boundary = []
        for c in range(C): boundary.append(grid[0][c])
        for r in range(1, R): boundary.append(grid[r][C-1])
        for c in range(C-2, -1, -1): boundary.append(grid[R-1][c])
        for r in range(R-2, 0, -1): boundary.append(grid[r][0])

        changes = 0
        first_val = None
        last_val = None
        for val in boundary:
            if val is not None:
                if first_val is None: first_val = val
                if last_val is not None and val != last_val:
                    changes += 1
                last_val = val
        if last_val is not None and first_val is not None and last_val != first_val:
            changes += 1
        return changes

    def is_valid_at(grid, r, c):
        """Checks local and global constraints after placing a cell at (r, c)."""
        for dr in [-1, 0]:
            for dc in [-1, 0]:
                if not check_2x2(grid, r + dr, c + dc):
                    return False
        if get_boundary_changes(grid) > 2:
            return False
        if not can_connect(grid, 'B') or not can_connect(grid, 'W'):
            return False
        return True

    def propagate(grid):
        """Applies deductive rules to fill in forced cells."""
        changed = True
        while changed:
            changed = False
            # 2x2 rule
            for r in range(R - 1):
                for c in range(C - 1):
                    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
                    vals = [grid[nr][nc] for nr, nc in cells]
                    if vals.count('B') == 3 and None in vals:
                        idx = vals.index(None)
                        nr, nc = cells[idx]
                        grid[nr][nc] = 'W'
                        if not is_valid_at(grid, nr, nc): return False
                        changed = True
                    elif vals.count('W') == 3 and None in vals:
                        idx = vals.index(None)
                        nr, nc = cells[idx]
                        grid[nr][nc] = 'B'
                        if not is_valid_at(grid, nr, nc): return False
                        changed = True
            # Boundary rule: if a boundary cell is forced by the 2-change limit
            boundary_indices = []
            for c in range(C): boundary_indices.append((0, c))
            for r in range(1, R): boundary_indices.append((r, C-1))
            for c in range(C-2, -1, -1): boundary_indices.append((R-1, c))
            for r in range(R-2, 0, -1): boundary_indices.append((r, 0))
            for r, c in boundary_indices:
                if grid[r][c] is None:
                    grid[r][c] = 'B'
                    if get_boundary_changes(grid) > 2:
                        grid[r][c] = 'W'
                        if not is_valid_at(grid, r, c): return False
                        changed = True
                    else:
                        grid[r][c] = 'W'
                        if get_boundary_changes(grid) > 2:
                            grid[r][c] = 'B'
                            if not is_valid_at(grid, r, c): return False
                            changed = True
                        else:
                            grid[r][c] = None
        return True

    # Pre-calculate empty cells and sort them by proximity to clues for better heuristic
    clues = [(r, c) for r in range(R) for c in range(C) if grid[r][c] is not None]
    empty_cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] is None]
    empty_cells.sort(key=lambda cell: min(abs(cell[0]-cr) + abs(cell[1]-cc) for cr, cc in clues))

    def backtrack(idx):
        if idx == len(empty_cells):
            if is_connected(grid, 'B') and is_connected(grid, 'W'):
                return [row[:] for row in grid]
            return None

        r, c = empty_cells[idx]
        if grid[r][c] is not None:
            return backtrack(idx + 1)

        for color in ['B', 'W']:
            snapshot = [row[:] for row in grid]
            grid[r][c] = color
            if is_valid_at(grid, r, c) and propagate(grid):
                res = backtrack(idx + 1)
                if res: return res
            # Undo changes
            for i in range(R):
                grid[i] = snapshot[i]
        return None

    # Initial propagation and start search
    if not propagate(grid):
        return "No Solution"
    result = backtrack(0)
    return result if result else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

